from itertools import combinations

def subsets_with_sum(arr, k, target_sum, used):
    """
    Helper function to check if there exists a subset of `arr` (excluding used elements)
    that sums up to target_sum.
    """
    for i in range(len(arr)):
        if not used[i] and arr[i] <= target_sum:
            used[i] = True
            if target_sum - arr[i] == 0 or subsets_with_sum(arr, k, target_sum - arr[i], used):
                return True
            used[i] = False
    return False

def can_partition(arr, k):
    """
    Main function to partition the array into k subsets with unique sums.
    """
    total_sum = sum(arr)
    if total_sum % k != 0:
        return False  # If not divisible, cannot partition into equal subsets

    subset_sum = total_sum // k
    used = [False] * len(arr)

    for _ in range(k):
        if not subsets_with_sum(arr, k, subset_sum, used):
            return False

    return True

