from collections import defaultdict, deque

def find_all_reachable_start_nodes(n, edges):
    """
    Returns a list of all possible starting nodes from which all nodes in the graph are reachable.

    Parameters:
    - n (int): The number of nodes in the graph, labeled from 0 to n-1.
    - edges (List[List[int]]): A list of directed edges where each edge is represented as [u, v].

    Returns:
    - List[int]: A sorted list of all possible starting nodes.
    """
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    # Build the graph and its reverse.
    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    def bfs(start, graph):
        visited = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return visited

    # Find nodes that can reach all other nodes
    all_reachable = set(range(n))
    for node in range(n):
        if len(bfs(node, graph)) != n:
            all_reachable.discard(node)

    return sorted(list(all_reachable))

def three_sum_closest(nums, target):
    """
    Returns the sum of the triplet in nums that is closest to the target.
    """
    nums.sort()
    closest_sum = float('inf')

    for i in range(len(nums) - 2):
        left, right = i + 1, len(nums) - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return current_sum
            if abs(current_sum - target) < abs(closest_sum - target):
                closest_sum = current_sum
            if current_sum < target:
                left += 1
            else:
                right -= 1

    return closest_sum

