def remove_adjacent_duplicates(S):
    """
    Removes all adjacent duplicates from the string S iteratively until no more adjacent duplicates exist.

    Parameters:
    S (str): The input string consisting of lowercase English letters.

    Returns:
    str: The string after removing all possible adjacent duplicates.
    """
    stack = []
    for char in S:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

