def longest_building_roster(heights):
    """
    Returns the length of the longest increasing subsequence in the given
    array `heights`.
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

