def num_lakes(grid):
    """
    Returns the number of lakes in the given 2D grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def dfs(x, y):
        if not is_valid(x, y) or visited[x][y] or grid[x][y] == 1:
            return
        visited[x][y] = True
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for dx, dy in directions:
            dfs(x + dx, y + dy)

    def is_surrounded_by_land(x, y):
        queue = [(x, y)]
        surrounded = True
        while queue:
            cx, cy = queue.pop(0)
            if not is_valid(cx, cy):
                surrounded = False
                continue
            if grid[cx][cy] == 1 or visited[cx][cy]:
                continue
            visited[cx][cy] = True
            directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
            for dx, dy in directions:
                queue.append((cx + dx, cy + dy))
        return surrounded

    lakes_count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and not visited[i][j]:
                if is_surrounded_by_land(i, j):
                    lakes_count += 1
    return lakes_count

def firstUniqChar(s):
    """
    Find the first non-repeating character in the string s and return its index.
    If it doesn't exist, return -1.
    """
    # Dictionary to count the occurrences of each character
    count = {}

    # Count the occurrences
    for char in s:
        count[char] = count.get(char, 0) + 1

    # Find the index of the first non-repeating character
    for index, char in enumerate(s):
        if count[char] == 1:
            return index

    # If no non-repeating character is found, return -1
    return -1

