def maximum_adjacent_difference(nums):
    """
    Return the maximum difference between the increasing adjacent elements in the array.
    If the array contains less than 2 elements, return 0.
    """
    if len(nums) < 2:
        return 0

    max_diff = 0
    for i in range(1, len(nums)):
        diff = nums[i] - nums[i - 1]
        if diff > 0:
            max_diff = max(max_diff, diff)

    return max_diff

