def solveSudoku(board):
    """
    Solves the Sudoku puzzle by modifying the input board in-place.
    """
    def is_valid(board, row, col, num):
        # Check if num is not in the given row, column and 3x3 sub-grid
        num = str(num)
        for i in range(9):
            if board[row][i] == num or board[i][col] == num:
                return False
        startRow, startCol = 3 * (row // 3), 3 * (col // 3)
        for i in range(startRow, startRow + 3):
            for j in range(startCol, startCol + 3):
                if board[i][j] == num:
                    return False
        return True

    def solve(board):
        for row in range(9):
            for col in range(9):
                if board[row][col] == '.':
                    for num in range(1, 10):
                        if is_valid(board, row, col, num):
                            board[row][col] = str(num)
                            if solve(board):
                                return True
                            board[row][col] = '.'
                    return False
        return True

    solve(board)

def longest_k_alternating_subarray(arr, k):
    """
    Returns the length of the longest k-alternating subarray.
    """
    if not arr or k <= 0:
        return 0

    max_length = 0
    current_length = 1
    n = len(arr)

    for i in range(1, n):
        if arr[i] != arr[i - 1]:
            current_length += 1
        else:
            current_length = 1

        if current_length > max_length:
            max_length = current_length

    return max_length if max_length >= k else 0

