def is_water_reachable(grid, K):
    """
    Determines if there exists at least one water cell (0) that is reachable from a land cell (1) within K steps.

    :param grid: List[List[int]] - 2D grid representing the map of the city
    :param K: int - Maximum number of steps a person can traverse from land to water
    :return: bool - True if there exists at least one reachable water cell within K steps, otherwise False
    """
    m, n = len(grid), len(grid[0])

    # Direction vectors for moving in four possible directions (up, down, left, right)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    from collections import deque
    queue = deque()

    # Finding all land cells to start BFS from
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j, 0))  # Starting point with initial distance 0

    while queue:
        x, y, dist = queue.popleft()

        if dist > K: 
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n:
                if grid[nx][ny] == 0 and dist + 1 <= K:
                    return True
                if grid[nx][ny] == 1:
                    queue.append((nx, ny, dist + 1))

    return False

