def can_form(word, words_set, memo):
    if word in memo:
        return memo[word]
    for i in range(1, len(word)):
        prefix = word[:i]
        suffix = word[i:]
        if prefix in words_set and (suffix in words_set or can_form(suffix, words_set, memo)):
            memo[word] = True
            return True
    memo[word] = False
    return False

def longest_concatenated_word(words):
    words_set = set(words)
    memo = {}
    longest_word = ""

    for word in words:
        if can_form(word, words_set, memo) and len(word) > len(longest_word):
            longest_word = word

    return longest_word

