import itertools
import math

def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def has_prime_pair(arr):
    """
    Determine if there exists a pair of indices (i, j) such that
    arr[i] + arr[j] is a prime number.
    """
    for i, j in itertools.combinations(range(len(arr)), 2):
        if is_prime(arr[i] + arr[j]):
            return True
    return False

