def max_jumps(arr, d):
    n = len(arr)
    memo = [-1] * n

    def dfs(i):
        if memo[i] != -1:
            return memo[i]

        max_step = 1  # We can always stay at the current index
        for j in range(i + 1, min(n, i + d + 1)):
            if arr[i] > arr[j]:
                max_step = max(max_step, 1 + dfs(j))
            else:
                break  # As soon as we find a j where arr[i] <= arr[j], no need to continue right

        for j in range(i - 1, max(-1, i - d - 1), -1):
            if arr[i] > arr[j]:
                max_step = max(max_step, 1 + dfs(j))
            else:
                break  # As soon as we find a j where arr[i] <= arr[j], no need to continue left

        memo[i] = max_step
        return max_step

    return max(dfs(i) for i in range(n))

def find_relative_ranks(scores):
    """
    Given scores of players, returns their ranking in terms of medals and numerical rank.
    """
    n = len(scores)
    if n == 0:
        return []

    sorted_indices = sorted(range(n), key=lambda x: scores[x], reverse=True)

    ranks = [""] * n

    for i in range(n):
        if i == 0:
            ranks[sorted_indices[i]] = "Gold Medal"
        elif i == 1:
            ranks[sorted_indices[i]] = "Silver Medal"
        elif i == 2:
            ranks[sorted_indices[i]] = "Bronze Medal"
        else:
            ranks[sorted_indices[i]] = str(i + 1)

    return ranks

