def largest_island(grid):
    from collections import deque

    def bfs(x, y, index):
        queue = deque([(x, y)])
        grid[x][y] = index
        size = 0
        while queue:
            cx, cy = queue.popleft()
            size += 1
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 1:
                    grid[nx][ny] = index
                    queue.append((nx, ny))
        return size

    def get_neighbors(x, y):
        neighbors = set()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
                neighbors.add(grid[nx][ny])
        return neighbors

    index = 2
    island_sizes = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                size = bfs(i, j, index)
                island_sizes[index] = size
                index += 1

    max_island = max(island_sizes.values(), default=0)
    result = max_island

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 0:
                neighbors = get_neighbors(i, j)
                combined_size = 1
                for n in neighbors:
                    if n > 1:
                        combined_size += island_sizes[n]
                result = max(result, combined_size)

    if result == 1:
        return max_island
    return result

