def smallest_string_after_reversals(s, n):
    """
    Returns the lexicographically smallest string obtainable by applying 
    the reverse operation exactly n times.
    """
    if n == 0:
        return s
    elif n == 1:
        # Find the smallest lexicographical order by reversing substrings
        result = s
        for k in range(len(s)):
            reversed_substring = s[:k+1][::-1] + s[k+1:]
            if reversed_substring < result:
                result = reversed_substring
        return result
    else:
        # When n >= 2, we can always achieve the fully sorted string
        return "".join(sorted(s))

def count_pairs(nums, target):
    """
    Count the number of pairs (i, j) such that nums[i] + nums[j] == target and i < j.
    """
    count = 0
    num_dict = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_dict:
            count += num_dict[complement]

        if num in num_dict:
            num_dict[num] += 1
        else:
            num_dict[num] = 1

    return count

