def count_sub_islands(grid1, grid2):
    """
    Returns the number of sub-islands in grid2 that are also islands in grid1.
    """

    def dfs(grid, x, y, visited):
        stack = [(x, y)]
        cells = []
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            cells.append((cx, cy))
            for nx, ny in [(cx+1, cy), (cx-1, cy), (cx, cy+1), (cx, cy-1)]:
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 1 and (nx, ny) not in visited:
                    stack.append((nx, ny))
        return cells

    m, n = len(grid1), len(grid1[0])
    visited2 = set()
    sub_islands_count = 0

    for i in range(m):
        for j in range(n):
            if grid2[i][j] == 1 and (i, j) not in visited2:
                sub_island_cells = dfs(grid2, i, j, visited2)
                if all(grid1[x][y] == 1 for x, y in sub_island_cells):
                    sub_islands_count += 1

    return sub_islands_count

