def can_form_square(sticks):
    if not sticks or sum(sticks) % 4 != 0:
        return False

    side_length = sum(sticks) // 4
    sides = [0] * 4
    sticks.sort(reverse=True)

    def dfs(i):
        if i == len(sticks):
            return sides[0] == sides[1] == sides[2] == sides[3] == side_length

        for j in range(4):
            if sides[j] + sticks[i] <= side_length:
                sides[j] += sticks[i]
                if dfs(i + 1):
                    return True
                sides[j] -= sticks[i]
            if sides[j] == 0:
                break

        return False

    return dfs(0)

