def heightMovement(heights):
    """
    Returns the minimum number of movements needed to achieve a non-decreasing height arrangement.
    """
    sorted_heights = sorted(heights)
    movements = 0

    for original, sorted_h in zip(heights, sorted_heights):
        if original != sorted_h:
            movements += 1

    return movements // 2  # Each mismatch involves two students, so divide by 2

