def max_profit(arr):
    """
    This function calculates the maximum possible profit from buying and selling the stock once.
    """
    if not arr or len(arr) < 2:
        return 0

    min_price = arr[0]
    max_profit = 0

    for price in arr[1:]:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

