def longest_consecutive_ones(nums):
    """
    Returns the length of the longest consecutive 1s in the array that can be achieved by performing at most one operation to flip one 0 to 1.
    """
    max_consecutive = 0
    num_zeros = 0
    left = 0

    for right in range(len(nums)):
        if nums[right] == 0:
            num_zeros += 1

        while num_zeros > 1:
            if nums[left] == 0:
                num_zeros -= 1
            left += 1

        max_consecutive = max(max_consecutive, right - left + 1)

    return max_consecutive

