def minimized_difference(nums, k):
    """
    Returns the minimized absolute difference found by selecting k integers from the list nums.
    """
    if not nums or k <= 0 or k > len(nums):
        return 0

    nums.sort()
    min_diff = float('inf')

    for i in range(len(nums) - k + 1):
        diff = nums[i + k - 1] - nums[i]
        if diff < min_diff:
            min_diff = diff

    return min_diff

