import heapq
from collections import defaultdict

def networkDelayTime(times, n, k):
    # Create adjacency list from the given times list
    graph = defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))

    # Min-heap priority queue to store (travel_time, intersection) pairs
    pq = [(0, k)]
    # Dictionary to keep track of the shortest travel time for each intersection
    shortest_times = {}

    while pq:
        travel_time, u = heapq.heappop(pq)

        if u in shortest_times:
            continue

        shortest_times[u] = travel_time

        for v, w in graph[u]:
            if v not in shortest_times:
                heapq.heappush(pq, (travel_time + w, v))

    if len(shortest_times) == n:
        return max(shortest_times.values())
    else:
        return -1

def is_connected_subset_sum(matrix, target):
    """
    Determines if there is a connected subset in the matrix whose sum is equal to the target sum.
    """
    # Directions for moving horizontally and vertically
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y, current_sum, visited):
        if current_sum == target:
            return True
        if current_sum > target:
            return False

        for direction in directions:
            nx, ny = x + direction[0], y + direction[1]
            if 0 <= nx < len(matrix) and 0 <= ny < len(matrix[0]) and not visited[nx][ny]:
                visited[nx][ny] = True
                if dfs(nx, ny, current_sum + matrix[nx][ny], visited):
                    return True
                visited[nx][ny] = False
        return False

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            visited = [[False]*len(matrix[0]) for _ in range(len(matrix))]
            visited[i][j] = True
            if dfs(i, j, matrix[i][j], visited):
                return True
    return False

def first_letter_to_appear_twice(s):
    """
    Returns the first letter to appear twice in the string s. If no such letter exists, returns an empty string.
    """
    seen = set()
    for char in s:
        if char in seen:
            return char
        seen.add(char)
    return ""

