def longest_equal_pos_neg_subarray(arr):
    """
    Returns the length of the longest subarray with an equal number of 
    positive and negative integers.
    """
    max_length = 0
    count_map = {0: -1}
    count = 0

    for i, num in enumerate(arr):
        if num > 0:
            count += 1
        elif num < 0:
            count -= 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

