def shift_string(s, k):
    """
    Shifts each character in the string s by k positions to the right in the English alphabet.
    """
    def shift_char(c, k):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + k) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + k) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, k) for c in s)

from itertools import permutations

def lexicographical_permutations(arr):
    """
    Returns all possible permutations of the given list of integers in lexicographical order.
    """
    return sorted([list(p) for p in permutations(arr)])

def nextGreaterElements(nums):
    """
    Returns the next greater numbers for each element in the circular array nums.
    """
    n = len(nums)
    result = [-1] * n
    stack = []

    for i in range(2 * n):
        while stack and nums[stack[-1]] < nums[i % n]:
            result[stack.pop()] = nums[i % n]
        if i < n:
            stack.append(i % n)

    return result

