        visited.add((x, y))
        shape.append((x - origin_x, y - origin_y))
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            dfs(x + dx, y + dy, origin_x, origin_y)
        return shape

    def normalize(shape):
        transformations = []
        for x, y in shape:
            transformations.extend([(x, y), (x, -y), (-x, y), (-x, -y),
                                    (y, x), (y, -x), (-y, x), (-y, -x)])
        distinct_shape = set(transformations)
        return tuple(sorted(distinct_shape))

    visited = set()
    distinct_islands = set()

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1 and (i, j) not in visited:
                shape = []
                dfs(i, j, i, j)
                if shape:
                    normalized_shape = normalize(shape)
                    distinct_islands.add(normalized_shape)

    return len(distinct_islands)

from collections import deque
from typing import List, Tuple

def minKnightMoves(grid: List[List[str]], start: Tuple[int, int], target: Tuple[int, int]) -> int:
    directions = [
        (-2, -1), (-1, -2),
        (-2,  1), ( 1, -2),
        ( 2, -1), (-1,  2),
        ( 2,  1), ( 1,  2)
    ]

    n = len(grid)
    visited = [[False] * n for _ in range(n)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and grid[x][y] != 'X'

    queue = deque([(start, 0)])
    while queue:
        (x, y), moves = queue.popleft()

        if (x, y) == target:
            return moves

        if visited[x][y]:
            continue

        visited[x][y] = True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and not visited[nx][ny]:
                queue.append(((nx, ny), moves + 1))

    return -1

