def largest_divisible_subset_size(nums):
    """
    Finds the size of the largest subset such that for every pair (num1, num2) in the subset,
    either num1 % num2 == 0 or num2 % num1 == 0
    """
    if not nums:
        return 0

    # Sort the list
    nums.sort()

    # DP array to store the largest subset ending at each element
    dp = [1] * len(nums)

    # Populate the DP array
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # Return the largest subset size found
    return max(dp)

