def longest_valid_parentheses(s):
    """
    Returns the length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with a base for the next valid substring

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

def can_jump_to_end(matrix):
    if not matrix or not matrix[0]:
        return False

    m, n = len(matrix), len(matrix[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(x, y):
        if x == m - 1 and y == n - 1:
            return True
        if visited[x][y]:
            return False

        visited[x][y] = True
        steps = matrix[x][y]
        for dx, dy in [(-steps, 0), (steps, 0), (0, -steps), (0, steps)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                if dfs(nx, ny):
                    return True

        return False

    return dfs(0, 0)

