def command_handler(commands):
    current_path = ["/"]
    output = []

    def get_path():
        if len(current_path) == 1:
            return "/"
        return "/" + "/".join(current_path[1:])

    for cmd in commands:
        if cmd.startswith("cd "):
            folder = cmd.split(" ", 1)[1]
            if folder == "..":
                if len(current_path) > 1:
                    current_path.pop()
            else:
                current_path.append(folder)
        elif cmd == "pwd":
            output.append(get_path())

    return output

