def longest_distinct_substring(s, k):
    """
    Returns the length of the longest distinct substring that contains exactly k distinct characters.
    If no such substring exists, returns 0.
    """
    n = len(s)
    if n == 0 or k == 0:
        return 0

    max_length = 0
    start = 0
    char_count = {}

    for end in range(n):
        char_count[s[end]] = char_count.get(s[end], 0) + 1

        while len(char_count) > k:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        if len(char_count) == k:
            max_length = max(max_length, end - start + 1)

    return max_length

import heapq
from collections import Counter, deque

def rearrange_string(s, k):
    if k <= 1:
        return s

    char_count = Counter(s)
    max_heap = [(-freq, char) for char, freq in char_count.items()]
    heapq.heapify(max_heap)

    queue = deque()
    result = []

    while max_heap:
        freq, char = heapq.heappop(max_heap)
        result.append(char)
        queue.append((char, freq + 1))

        if len(queue) < k:
            continue

        prev_char, prev_freq = queue.popleft()
        if -prev_freq > 0:
            heapq.heappush(max_heap, (prev_freq, prev_char))

    if len(result) != len(s):
        return ""

    return "".join(result)

