from collections import defaultdict, deque
from typing import List

def findLadders(beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
    def add_path(path, word):
        return path + [word]

    def add_intermediate_words(word):
        for i in range(len(word)):
            yield word[:i] + '*' + word[i+1:]

    def bfs_paths(source, target):
        if source == target:
            return [[source]]

        queue = deque([[beginWord]])
        visited = set(beginWord)
        found = False
        layers = []

        while queue and not found:
            local_visited = set()
            layer = []

            for _ in range(len(queue)):
                path = queue.popleft()
                current_word = path[-1]

                for intermediate in add_intermediate_words(current_word):
                    for next_word in all_combo_dict[intermediate]:
                        if next_word == target:
                            found = True
                            layer.append(add_path(path, next_word))
                        if next_word not in visited:
                            queue.append(add_path(path, next_word))
                            local_visited.add(next_word)
            if layer:
                layers.extend(layer)
            visited = visited.union(local_visited)

        return layers

    if endWord not in wordList or not endWord or not beginWord:
        return []

    all_combo_dict = defaultdict(list)
    for word in wordList:
        for intermediate in add_intermediate_words(word):
            all_combo_dict[intermediate].append(word)

    return bfs_paths(beginWord, endWord)

