def check_collinear(points):
    """
    Returns True if there exist at least one set of 3 or more points that are collinear, False otherwise.
    """
    if len(points) < 3:
        return False

    def slope(p1, p2):
        if p1[0] == p2[0]:
            return float('inf')
        return (p1[1] - p2[1]) / (p1[0] - p2[0])

    n = len(points)

    for i in range(n):
        slopes = {}
        for j in range(n):
            if i != j:
                m = slope(points[i], points[j])
                if m in slopes:
                    slopes[m] += 1
                else:
                    slopes[m] = 1

        for count in slopes.values():
            if count >= 2: # count >= 2 means at least 3 points including the original point
                return True

    return False

