def count_pairs_with_sum(arr, target):
    """
    Counts distinct pairs (i, j) in the array such that arr[i] + arr[j] == target.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    return len(pairs)

