import collections

def numMatchingSubseq(s: str, words: List[str]) -> int:
    """
    Returns the number of strings in words which are subsequences of s.
    """
    def is_subsequence(word, s):
        it = iter(s)
        return all(char in it for char in word)

    count = 0
    for word in words:
        if is_subsequence(word, s):
            count += 1

    return count

def find_customers_exceeding_threshold(transactions, threshold):
    """
    Returns a list of customer ids whose balance exceeds the given threshold after processing all transactions.

    Parameters:
    transactions (list of lists): A 2D integer list where each inner list represents a transaction [customer_id, amount].
    threshold (int): The maximum allowed balance for any customer.

    Returns:
    list: A sorted list of customer ids whose balance exceeds the threshold.
    """
    balances = {}

    for customer_id, amount in transactions:
        if customer_id in balances:
            balances[customer_id] += amount
        else:
            balances[customer_id] = amount

    exceeding_customers = [customer_id for customer_id, balance in balances.items() if balance > threshold]

    return sorted(exceeding_customers)

def min_deletions_to_form(word1, word2):
    """
    Determine if word2 can be formed from word1 and 
    calculate the minimum number of deletions required in word1 to form word2.
    """
    m, n = len(word1), len(word2)

    # Step 1: Use Dynamic Programming to find the Longest Common Subsequence (LCS)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    # Step 2: Check if the LCS length is equal to the length of word2
    if lcs_length != n:
        return -1
    else:
        # Minimum deletions to transform word1 into word2
        return m - lcs_length

