def max_subarray_sum(arr):
    """
    Returns the sum of the subarray with the maximum sum in a given array using Kadane's Algorithm.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

