def evaluate(expression):
    """
    Evaluates the mathematical expression where * has higher precedence than +.
    """
    # Remove any spaces from the expression
    expression = expression.replace(" ", "")

    def apply_operation(operands, operator):
        right = operands.pop()
        left = operands.pop()
        if operator == '+':
            operands.append(left + right)
        elif operator == '*':
            operands.append(left * right)

    # Stack for operands and operators
    operands = []
    operators = []
    i = 0

    while i < len(expression):
        char = expression[i]

        if char.isdigit():
            # Read the entire number
            start = i
            while i < len(expression) and expression[i].isdigit():
                i += 1
            operands.append(int(expression[start:i]))
            continue

        if char == '*':
            while operators and operators[-1] == '*':
                apply_operation(operands, operators.pop())
            operators.append(char)

        elif char == '+':
            while operators and operators[-1] in {'*', '+'}:
                apply_operation(operands, operators.pop())
            operators.append(char)

        i += 1

    while operators:
        apply_operation(operands, operators.pop())

    return operands[0]

