import math
from typing import List

def gcd_of_list(numbers: List[int]) -> int:
    return math.gcd(*numbers)

def count_subarrays_with_gcd_at_least_k(arr: List[int], k: int) -> int:
    n = len(arr)
    count = 0

    for i in range(n):
        current_gcd = 0
        for j in range(i, n):
            current_gcd = math.gcd(current_gcd, arr[j])
            if current_gcd < k:
                break
            count += 1
    return count

