def min_task_diff(tasks):
    """
    Returns the minimum possible difference between the total durations 
    of tasks assigned to two workers.
    """
    total_time = sum(tasks)
    n = len(tasks)
    dp = [[False] * (total_time // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_time // 2, -1, -1):
            if dp[i-1][j]:
                dp[i][j] = True
            if j >= tasks[i-1]:
                if dp[i-1][j-tasks[i-1]]:
                    dp[i][j] = True

    closest_sum = 0
    for j in range(total_time // 2, -1, -1):
        if dp[n][j]:
            closest_sum = j
            break

    return total_time - 2 * closest_sum

