def fullJustify(words, maxWidth):
    def justifyLine(line, lineLength, maxWidth, isLastLine=False):
        if len(line) == 1 or isLastLine:
            return ' '.join(line).ljust(maxWidth)
        totalSpaces = maxWidth - lineLength
        minSpaces = totalSpaces // (len(line) - 1)
        extraSpaces = totalSpaces % (len(line) - 1)

        for i in range(extraSpaces):
            line[i] += ' '

        return (' ' * minSpaces).join(line)

    result = []
    currentLine = []
    currentLineLength = 0

    for word in words:
        if currentLineLength + len(word) + len(currentLine) > maxWidth:
            result.append(justifyLine(currentLine, currentLineLength, maxWidth))
            currentLine = []
            currentLineLength = 0
        currentLine.append(word)
        currentLineLength += len(word)

    result.append(justifyLine(currentLine, currentLineLength, maxWidth, isLastLine=True))

    return result

