def num_surrounded_lakes(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Function to perform a DFS to mark all connected 0s starting from (i, j)
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x >= 0 and x < m and y >= 0 and y < n and grid[x][y] == 0:
                grid[x][y] = '#'
                stack.append((x + 1, y))
                stack.append((x - 1, y))
                stack.append((x, y + 1))
                stack.append((x, y - 1))

    # First, mark all lakes connected to the boundary
    for i in range(m):
        if grid[i][0] == 0:
            dfs(i, 0)
        if grid[i][n - 1] == 0:
            dfs(i, n - 1)
    for j in range(n):
        if grid[0][j] == 0:
            dfs(0, j)
        if grid[m - 1][j] == 0:
            dfs(m - 1, j)

    # Now, count the remaining surrounded lakes
    surrounded_lakes_count = 0
    for i in range(1, m - 1):
        for j in range(1, n - 1):
            if grid[i][j] == 0:
                surrounded_lakes_count += 1
                dfs(i, j)

    return surrounded_lakes_count

