def most_frequent_character(s):
    """
    Returns the most frequently occurring character in the string `s`.
    In case of a tie, returns the character that appears first.
    Spaces are ignored and uppercase and lowercase letters are distinct.
    """
    from collections import defaultdict

    # Dictionary to keep track of character counts and their first occurrence index
    char_count = defaultdict(int)
    first_occurrence = {}

    for index, char in enumerate(s):
        if char != ' ':
            if char not in first_occurrence:
                first_occurrence[char] = index
            char_count[char] += 1

    # Find the most frequent character with the earliest appearance in case of ties
    max_count = 0
    most_frequent_char = None
    for char, count in char_count.items():
        if (count > max_count) or (count == max_count and first_occurrence[char] < first_occurrence[most_frequent_char]):
            max_count = count
            most_frequent_char = char

    return most_frequent_char

