from bisect import bisect_left

def min_removals_to_increase_order(heights):
    """
    Determines the minimum number of people to remove from the queue so that the remaining heights are in
    non-decreasing order.

    :param heights: List of integers representing the heights of people in the queue.
    :return: Integer representing the minimum number of people to remove.
    """
    def length_of_lis(seq):
        lis = []
        for height in seq:
            pos = bisect_left(lis, height)
            if pos == len(lis):
                lis.append(height)
            else:
                lis[pos] = height
        return len(lis)

    n = len(heights)
    lis_length = length_of_lis(heights)
    return n - lis_length

