def rob(nums):
    """
    Returns the maximum amount of money that can be robbed, considering the houses are arranged in a circle.
    """
    if len(nums) == 1:
        return nums[0]

    def rob_linear(houses):
        """
        Helper function to calculate the maximum amount that can be robbed from a linear arrangement of houses.
        """
        prev = curr = 0
        for amount in houses:
            prev, curr = curr, max(curr, prev + amount)
        return curr

    return max(rob_linear(nums[1:]), rob_linear(nums[:-1]))

