def min_bridges_needed(arr):
    """
    Returns the minimum number of bridges needed to connect all the separate land masses.
    Each 1 represents land and each 0 represents water.
    """
    if arr.count(1) == 0:
        return 0

    land_groups = 0
    length = len(arr)
    i = 0

    while i < length:
        if arr[i] == 1:
            land_groups += 1
            while i < length and arr[i] == 1:
                i += 1
        i += 1

    if land_groups <= 1:
        return 0
    else:
        return land_groups - 1

