from typing import List

def find_indices(nums: List[int], target: int) -> List[int]:
    """
    Finds two distinct indices i and j such that nums[i] + nums[j] == target.
    Returns a list of the indices sorted in ascending order.
    If no such pair exists, returns an empty list.
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return sorted([seen[complement], i])
        seen[num] = i
    return []

