def length_of_lis(nums):
    """
    Returns the length of the longest non-decreasing subsequence of the array nums.
    """
    if not nums:
        return 0

    # Initialize the sub list to keep our increasing subsequence
    sub = []

    for num in nums:
        # If num is greater than the largest element in sub
        if len(sub) == 0 or num >= sub[-1]:
            sub.append(num)
        else:
            # Find the first element in sub which is greater than or equal to num and replace it
            left, right = 0, len(sub) - 1
            while left < right:
                mid = (left + right) // 2
                if sub[mid] < num:
                    left = mid + 1
                else:
                    right = mid
            sub[left] = num

    return len(sub)

