def min_bridges_to_connect_islands(matrix):
    from collections import deque
    from itertools import product

    rows = len(matrix)
    cols = len(matrix[0])

    def bfs(start):
        queue = deque([start])
        visited = set([start])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and matrix[nr][nc] == 1:
                    queue.append((nr, nc))
                    visited.add((nr, nc))
        return visited

    def get_all_islands():
        islands = []

        visited = set()
        for r, c in product(range(rows), range(cols)):
            if matrix[r][c] == 1 and (r,c) not in visited:
                island = bfs((r, c))
                visited.update(island)
                islands.append(island)

        return islands

    islands = get_all_islands()

    if len(islands) == 1:
        return 0

    def shortest_distance(set1, set2):
        min_distance = float('inf')
        for r1, c1 in set1:
            for r2, c2 in set2:
                distance = abs(r1 - r2) + abs(c1 - c2)
                min_distance = min(min_distance, distance)
        return min_distance - 1  # minus 1 because one step already counts for a conversion

    min_conversion = float('inf')

    for i in range(len(islands)):
        for j in range(i + 1, len(islands)):
            distance = shortest_distance(islands[i], islands[j])
            min_conversion = min(min_conversion, distance)

    return min_conversion

def lexicographically_smallest_subsequence(s, k):
    """
    Returns the lexicographically smallest subsequence of length k from string s.
    """
    stack = []
    n = len(s)

    for i, char in enumerate(s):
        while stack and len(stack) + (n - i) > k and stack[-1] > char:
            stack.pop()
        if len(stack) < k:
            stack.append(char)

    return ''.join(stack)

