def largest_group_of_water(grid, k):
    from collections import deque

    def bfs(x, y):
        queue = deque([(x, y)])
        visited.add((x, y))
        group_size = 1
        while queue:
            cx, cy = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited and grid[nx][ny] == 1:
                    valid_neighbor = False
                    # Check if there is at least one water cell within distance k
                    for i in range(-k, k+1):
                        for j in range(-k, k+1):
                            if abs(i) + abs(j) <= k:
                                ni, nj = nx + i, ny + j
                                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]) and grid[ni][nj] == 1:
                                    valid_neighbor = True
                                    break
                        if valid_neighbor:
                            break
                    if valid_neighbor:
                        visited.add((nx, ny))
                        queue.append((nx, ny))
                        group_size += 1
        return group_size

    max_size = 0
    visited = set()

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1 and (i, j) not in visited:
                max_size = max(max_size, bfs(i, j))

    return max_size

