def count_missing_numbers(nums):
    """
    Returns the number of positive integers that are missing from the list.
    """
    n = len(nums)
    present = [False] * n

    for num in nums:
        if 1 <= num <= n:
            present[num - 1] = True

    missing_count = 0
    for present_flag in present:
        if not present_flag:
            missing_count += 1

    return missing_count

