def number_of_focal_subarrays(nums, k):
    """
    Returns the number of focal subarrays that contain exactly k odd numbers.
    """
    count = 0
    odd_count = 0
    prefix_counts = {0: 1}

    for num in nums:
        if num % 2 == 1:
            odd_count += 1

        if odd_count - k in prefix_counts:
            count += prefix_counts[odd_count - k]

        if odd_count in prefix_counts:
            prefix_counts[odd_count] += 1
        else:
            prefix_counts[odd_count] = 1

    return count

