def shortest_substring_with_all_uniques(s):
    """
    Returns the length of the shortest substring containing all unique characters of the original string.
    """
    if not s:
        return 0

    unique_chars = set(s)
    unique_chars_count = len(unique_chars)

    left = 0
    char_count = {}
    min_length = len(s) + 1
    unique_counter = 0

    for right in range(len(s)):
        right_char = s[right]
        if right_char in char_count:
            if char_count[right_char] == 0:
                unique_counter += 1
            char_count[right_char] += 1
        else:
            char_count[right_char] = 1
            unique_counter += 1

        while unique_counter == unique_chars_count:
            current_length = right - left + 1
            if current_length < min_length:
                min_length = current_length

            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                unique_counter -= 1
            left += 1

    return min_length

