def max_cakes(ingredients, available):
    """
    Calculates the maximum number of cakes that can be baked with the given ingredients and available quantities.

    :param ingredients: List[int] - quantities of ingredients required for a single cake
    :param available: List[int] - quantities of ingredients available
    :return: int - maximum number of cakes that can be baked
    """
    if len(ingredients) != len(available):
        raise ValueError("The length of ingredients and available must be the same")

    return min(available[i] // ingredients[i] for i in range(len(ingredients)))

