def maximum_candies(candies):
    """
    Returns the maximum number of candies that one box can contain 
    after performing exactly one operation.
    """
    if not candies or len(candies) < 2:
        return 0

    max_candies = 0

    # Find maximum pairs sum and the maximum single value in the list
    for i in range(len(candies)):
        # Check pairs sums
        for j in range(i + 1, len(candies)):
            max_candies = max(max_candies, candies[i] + candies[j])

    return max(max_candies, max(candies))

