def judgeCircle(s):
    """
    Determines if the robot returns to the origin after completing all the moves.

    :param s: A string representing a sequence of moves ('U', 'D', 'L', 'R')
    :return: True if the robot returns to the origin, False otherwise
    """
    # Initial position
    x, y = 0, 0

    # Traverse through each move in the sequence
    for move in s:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    # Check if robot is back at the origin
    return x == 0 and y == 0

