def has_path(matrix, start, destination):
    """
    Determines if there is a path from start to destination in a 2D grid.
    """
    def is_valid(x, y):
        return 0 <= x < len(matrix) and 0 <= y < len(matrix[0]) and matrix[x][y] == 0

    def dfs(x, y):
        if not is_valid(x, y):
            return False
        if (x, y) == destination:
            return True
        matrix[x][y] = 2  # Mark as visited
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dfs(x + dx, y + dy):
                return True
        return False

    return dfs(start[0], start[1])

