def longest_subsequence_with_k_distinct(nums, k):
    from collections import defaultdict

    def at_most_k_distinct(nums, k):
        start = 0
        count = defaultdict(int)
        max_length = 0

        for end in range(len(nums)):
            count[nums[end]] += 1
            while len(count) > k:
                count[nums[start]] -= 1
                if count[nums[start]] == 0:
                    del count[nums[start]]
                start += 1
            max_length = max(max_length, end - start + 1)

        return max_length

    return at_most_k_distinct(nums, k)

