def can_form_by_deleting_one(s, t):
    """
    Determines if string t can be obtained by deleting exactly one character
    from string s and rearranging the remaining characters.
    """
    if len(s) != len(t) + 1:
        return False

    s_counter = {}
    t_counter = {}

    # Count the frequency of each character in s
    for char in s:
        if char in s_counter:
            s_counter[char] += 1
        else:
            s_counter[char] = 1

    # Count the frequency of each character in t
    for char in t:
        if char in t_counter:
            t_counter[char] += 1
        else:
            t_counter[char] = 1

    # Check if t_counter matches s_counter with exactly one less character
    diff_count = 0
    for char in s_counter:
        s_count = s_counter.get(char, 0)
        t_count = t_counter.get(char, 0)
        if s_count != t_count:
            diff_count += 1
            if diff_count > 1 or t_count != s_count - 1:
                return False

    return True

def search_insert(nums, target):
    """
    Returns the index at which target should be inserted in nums to maintain the sorted order.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

