def aggregate_transactions(transactions):
    """
    Aggregates transaction amounts by name.

    :param transactions: List of strings, each in the format "name amount".
    :return: Dictionary where the keys are the names and the values are the total amounts.
    """
    result = {}
    for transaction in transactions:
        name, amount = transaction.split()
        amount = int(amount)
        if name in result:
            result[name] += amount
        else:
            result[name] = amount
    return result

