    n = len(s)
    operations = 0
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            operations += 1
    return operations

def find_indices(nums, x):
    """
    Returns true if there are two distinct indices i and j in the array 
    such that nums[i] + nums[j] == x, otherwise false.
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = x - num
        if complement in seen:
            return True
        seen[num] = i
    return False

