def min_cost_with_layover(flights, src, dst):
    """
    Returns the minimum cost to travel from src to dst with up to one layover.
    If no such route exists, -1 is returned.
    """
    # Initialize dictionaries to store direct flights and layover flights
    direct_flights = {}   # Direct flights from src
    layover_flights = {}  # Layover flights from intermediate city

    for flight in flights:
        from_city, to_city, price = flight

        # Process direct flight
        if from_city == src:
            if to_city not in direct_flights or price < direct_flights[to_city]:
                direct_flights[to_city] = price

        # Process layover flight
        if from_city != src:
            if from_city not in layover_flights:
                layover_flights[from_city] = {}
            layover_flights[from_city][to_city] = price

    # Calculate minimum costs using direct flight and layover combination
    min_cost = float('inf')
    if dst in direct_flights:
        min_cost = direct_flights[dst]

    for intermediate_city in direct_flights:
        if intermediate_city in layover_flights and dst in layover_flights[intermediate_city]:
            layover_cost = direct_flights[intermediate_city] + layover_flights[intermediate_city][dst]
            if layover_cost < min_cost:
                min_cost = layover_cost

    return min_cost if min_cost != float('inf') else -1

