def longest_subsequence_sum_k(nums, k):
    """
    Returns the length of the longest subsequence with a sum equal to k.
    If no such subsequence exists, returns 0.
    """
    n = len(nums)
    dp = [-float('inf')] * (k + 1)  # Initialize dp array
    dp[0] = 0  # Base case: sum of 0 with 0 elements

    for num in nums:
        for s in range(k, num - 1, -1):
            if dp[s - num] != -float('inf'):
                dp[s] = max(dp[s], dp[s - num] + 1)

    return dp[k] if dp[k] != -float('inf') else 0

