def generate_parentheses(n):
    """
    Generate all possible strings of length 2*n that consist of balanced parentheses.

    Parameters:
    n (int): The number of pairs of parentheses.

    Returns:
    List[str]: A list of all balanced parentheses combinations of length 2*n sorted in lexicographical order.
    """
    result = []

    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            result.append(s)
            return
        if left < n:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)

    backtrack()
    return sorted(result)

