import heapq
from collections import defaultdict

def highest_quality_path(n, edges, quality):
    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Use Dijkstra's algorithm to find the maximum quality path from node 1 to node n
    pq = [(-quality[0], 1)]  # Use a max-heap by inserting negative quality values
    max_quality = {1: quality[0]}

    while pq:
        curr_quality, node = heapq.heappop(pq)
        curr_quality = -curr_quality

        if node == n:
            return curr_quality

        for neighbor, weight in graph[node]:
            path_quality = min(curr_quality, quality[neighbor - 1])
            if neighbor not in max_quality or path_quality > max_quality[neighbor]:
                max_quality[neighbor] = path_quality
                heapq.heappush(pq, (-path_quality, neighbor))

    return -1

