from typing import List, Tuple
import heapq

def minimum_threshold(heights: List[List[int]]) -> int:
    def can_traverse(threshold: int) -> bool:
        m, n = len(heights), len(heights[0])
        visited = [[False] * n for _ in range(m)]
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        heap = [(0, 0, 0)]  # (cost, x, y)
        heapq.heapify(heap)
        visited[0][0] = True

        while heap:
            cost, x, y = heapq.heappop(heap)
            if x == m-1 and y == n-1:
                return True
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                    diff = abs(heights[nx][ny] - heights[x][y])
                    if diff <= threshold:
                        visited[nx][ny] = True
                        heapq.heappush(heap, (cost + diff, nx, ny))
        return False

    if not heights or not heights[0]:
        return -1

    left, right = 0, max(max(row) for row in heights)
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if can_traverse(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

