def maxProfit(k, prices):
    """
    This function calculates the maximum profit from at most k stock transactions.

    :param k: Maximum number of transactions
    :param prices: List of daily stock prices
    :return: Maximum possible profit with at most k transactions
    """
    if not prices:
        return 0

    n = len(prices)

    if k >= n // 2:
        return sum(max(prices[i + 1] - prices[i], 0) for i in range(n - 1))

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - prices[j])

    return dp[k][n - 1]

def max_area_of_island(matrix):
    """
    Returns the maximum area of an island in the given 2D matrix.
    """
    if not matrix or not matrix[0]:
        return 0

    max_area = 0
    rows, cols = len(matrix), len(matrix[0])

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or matrix[r][c] == 0:
            return 0
        matrix[r][c] = 0  # mark as visited
        area = 1
        area += dfs(r+1, c)
        area += dfs(r-1, c)
        area += dfs(r, c+1)
        area += dfs(r, c-1)
        return area

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                max_area = max(max_area, dfs(r, c))

    return max_area

