def subset_sum(prices, M):
    """
    Determines if there exists a subset of prices that adds up to M.

    :param prices: List of integers representing the prices of items.
    :param M: Integer representing the target amount.
    :return: True if there exists a subset of prices that add up to M, otherwise False.
    """
    n = len(prices)
    subset = [[False] * (M + 1) for _ in range(n + 1)]

    # Initialize the first column as True, since a sum of 0 can always be achieved with an empty set.
    for i in range(n + 1):
        subset[i][0] = True

    # Fill the subset table in bottom up manner
    for i in range(1, n + 1):
        for j in range(1, M + 1):
            if prices[i - 1] > j:
                subset[i][j] = subset[i - 1][j]
            else:
                subset[i][j] = subset[i - 1][j] or subset[i - 1][j - prices[i - 1]]

    return subset[n][M]

