def count_valid_subarrays(arr, k):
    """
    Returns the number of valid subarrays of length k whose sum is divisible by k.
    """
    n = len(arr)
    if k > n:
        return 0

    count = 0
    for i in range(n - k + 1):
        subarray_sum = sum(arr[i:i+k])
        if subarray_sum % k == 0:
            count += 1

    return count

