def water_flow_to_edge(grid):
    """
    Returns the number of cells in the grid from which water can eventually flow to the edge
    of the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    def bfs(starts):
        visited = set(starts)
        queue = list(starts)
        while queue:
            x, y = queue.pop(0)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] >= grid[x][y]:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        return visited

    # BFS from all cells at the edge
    edge_cells = [(i, j) for i in range(m) for j in range(n) if i in {0, m-1} or j in {0, n-1}]
    edge_reachable = bfs(edge_cells)

    return len(edge_reachable)

