def max_additional_people(arr):
    n = len(arr)
    if n == 0:
        return 0

    def can_seat(i):
        return arr[i] == 0 and arr[(i - 1) % n] == 0 and arr[(i + 1) % n] == 0

    seated = arr.count(1)
    if seated == n:
        return 0

    max_additional = 0
    for i in range(n):
        if can_seat(i):
            arr[i] = 1
            max_additional += 1

    return max_additional

