def max_non_adjacent_sum(nums):
    """
    Return the maximum sum using a subsequence where no two elements are adjacent.
    """
    if not nums:
        return 0
    n = len(nums)
    if n == 1:
        return max(0, nums[0])
    if n == 2:
        return max(0, max(nums[0], nums[1]))

    prev_one = max(0, max(nums[0], nums[1]))
    prev_two = max(0, nums[0])

    for i in range(2, n):
        current = max(prev_one, prev_two + nums[i])
        prev_two = prev_one
        prev_one = current

    return prev_one

