def is_valid_distribution(A, N, K, max_pages):
    required_students = 1
    current_pages = 0

    for pages in A:
        if current_pages + pages > max_pages:
            required_students += 1
            current_pages = pages
            if required_students > K:
                return False
        else:
            current_pages += pages

    return True

def find_minimum_pages(A, N, K):
    if K > N:
        return -1  # More students than books, impossible to allocate

    low = max(A)
    high = sum(A)
    result = high

    while low <= high:
        mid = (low + high) // 2
        if is_valid_distribution(A, N, K, mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

def maxNumberOfEventDays(events, k):
    events.sort(key=lambda x: x[1])  # sort events by their end days
    attended_days = [0] * 100000  # assume largest day can be 100000

    number_of_events_attended = 0
    for event in events:
        start, end = event
        for day in range(start, end + 1):
            if attended_days[day] == 0 and number_of_events_attended < k:
                attended_days[day] = 1
                number_of_events_attended += 1
                break

    return sum(attended_days)

# Example usage:
# events = [[1, 2], [2, 3], [3, 4]]
# k = 2
# print(maxNumberOfEventDays(events, k))  # Output: 2 (can choose event [1, 2] and event [3, 4])

