def evaluate_expression(s):
    """
    Evaluates an arithmetic expression and returns the result.
    The expression contains digits and the characters '+', '-', '*', '/'.
    """
    def apply_operator(operands, operator):
        right = operands.pop()
        left = operands.pop()
        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(int(left / right))  # Truncate towards zero.

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operands = []
    operators = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            val = 0
            while i < len(s) and s[i].isdigit():
                val = val * 10 + int(s[i])
                i += 1
            operands.append(val)
            i -= 1  # to accommodate the increment from the while loop back into the main one.
        else:
            while (operators and precedence(operators[-1]) >= precedence(s[i])):
                apply_operator(operands, operators.pop())
            operators.append(s[i])
        i += 1

    while operators:
        apply_operator(operands, operators.pop())

    return operands[0]

def count_unique_substrings(s, k):
    """
    Returns the number of unique substrings of length k in the given string s.
    """
    if k > len(s):
        return 0

    unique_substrings = set()
    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        unique_substrings.add(substring)

    return len(unique_substrings)

