def pacificAtlantic(matrix):
    """
    Given a matrix of heights, return list of grid coordinates
    where water can flow to both Pacific and Atlantic Oceans.
    """
    if not matrix:
        return []

    def dfs(matrix, i, j, visited):
        directions = [(0,1), (1,0), (0,-1), (-1,0)]
        visited.add((i, j))
        for d in directions:
            x, y = i + d[0], j + d[1]
            if 0 <= x < len(matrix) and 0 <= y < len(matrix[0]) and (x, y) not in visited and matrix[x][y] >= matrix[i][j]:
                dfs(matrix, x, y, visited)

    m, n = len(matrix), len(matrix[0])
    pacific_visited = set()
    atlantic_visited = set()

    for i in range(m):
        dfs(matrix, i, 0, pacific_visited)
        dfs(matrix, i, n-1, atlantic_visited)

    for j in range(n):
        dfs(matrix, 0, j, pacific_visited)
        dfs(matrix, m-1, j, atlantic_visited)

    return list(pacific_visited & atlantic_visited)

def longest_substring_with_k_distinct(t, k):
    """
    Finds and returns the longest substring of t that contains at most k distinct characters.
    """
    if k == 0 or not t:
        return ""

    window_start = 0
    max_length = 0
    max_substr = ""
    char_frequency = {}

    for window_end in range(len(t)):
        end_char = t[window_end]
        if end_char not in char_frequency:
            char_frequency[end_char] = 0
        char_frequency[end_char] += 1

        while len(char_frequency) > k:
            start_char = t[window_start]
            char_frequency[start_char] -= 1
            if char_frequency[start_char] == 0:
                del char_frequency[start_char]
            window_start += 1

        if (window_end - window_start + 1) > max_length:
            max_length = window_end - window_start + 1
            max_substr = t[window_start:window_end+1]

    return max_substr

