def min_knight_removals(board):
    def can_threaten(x1, y1, x2, y2):
        return (
            x1 == x2 or y1 == y2 or
            (abs(x1 - x2), abs(y1 - y2)) in [(1, 2), (2, 1)],
        )

    def dfs(i, j, visited):
        stack = [(i, j)]
        component = []
        while stack:
            x, y = stack.pop()
            if (x, y) not in visited:
                visited.add((x, y))
                component.append((x, y))
                for nx in range(n):
                    for ny in range(m):
                        if board[nx][ny] == 1 and can_threaten(x, y, nx, ny) and (nx, ny) not in visited:
                            stack.append((nx, ny))
        return component

    n = len(board)
    m = len(board[0]) if n > 0 else 0
    visited = set()
    components = []

    for i in range(n):
        for j in range(m):
            if board[i][j] == 1 and (i, j) not in visited:
                components.append(dfs(i, j, visited))

    total_remove = 0
    for component in components:
        total_remove += len(component) - 1

    return total_remove

def num_decodings(s: str) -> int:
    if not s:
        return 0
    if s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        one_digit = int(s[i-1:i])
        two_digits = int(s[i-2:i])

        if one_digit >= 1:
            dp[i] += dp[i-1]

        if 10 <= two_digits <= 26:
            dp[i] += dp[i-2]

    return dp[n]

