def is_anagram(s, t):
    """
    Returns True if t is an anagram of s, otherwise False.
    """
    # Anagrams must have the same length
    if len(s) != len(t):
        return False

    # Create frequency dictionaries for each string
    freq_s = {}
    freq_t = {}

    for char in s:
        freq_s[char] = freq_s.get(char, 0) + 1

    for char in t:
        freq_t[char] = freq_t.get(char, 0) + 1

    # Compare frequency dictionaries
    return freq_s == freq_t

def minimum_steps(heights):
    n = len(heights)
    if n == 1:
        return 0

    steps = 0
    i = 0

    while i < n - 1:
        if heights[i + 1] >= heights[i]:
            i += 1
        else:
            if i + 2 < n and heights[i + 2] >= heights[i]:
                i += 2
            else:
                return -1
        steps += 1

    return steps

