def largest_square_island(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    max_side = 0

    # dp[i][j] represents the side length of the largest square ending at (i, j)
    dp = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # The largest square ending at the first row or column is the cell itself if it is land
                else:
                    # Update dp value only if the current cell is land
                    if grid[i][j] == 1:
                        dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

