def min_deletions_to_non_decreasing(s):
    """
    Returns the minimum number of deletions required to transform the string
    into a non-decreasing string where all 'X's come before all 'Y's.
    """
    x_count = 0
    y_count = 0
    result = float('inf')

    for char in s:
        if char == 'Y':
            y_count += 1

    result = min(result, y_count)

    for char in s:
        if char == 'X':
            x_count += 1
        else:
            y_count -= 1
        result = min(result, x_count + y_count)

    return result

