def remove_duplicate_letters(s):
    """
    Removes duplicate letters from the string s such that each letter appears only once
    and returns the result in the smallest lexicographical order.
    """
    stack = []
    seen = set()
    last_occurrence = {char: idx for idx, char in enumerate(s)}

    for idx, char in enumerate(s):
        if char not in seen:
            while stack and char < stack[-1] and idx < last_occurrence[stack[-1]]:
                seen.remove(stack.pop())
            seen.add(char)
            stack.append(char)

    return ''.join(stack)

