def longestIncreasingPath(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[-1 for _ in range(cols)] for _ in range(rows)]

    def dfs(x, y):
        if dp[x][y] != -1:
            return dp[x][y]
        dirs = [(1,0), (0,1), (-1,0), (0,-1)]
        max_path = 1
        for d in dirs:
            nx, ny = x + d[0], y + d[1]
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] > grid[x][y]:
                max_path = max(max_path, 1 + dfs(nx, ny))
        dp[x][y] = max_path
        return dp[x][y]

    longest = 0
    for r in range(rows):
        for c in range(cols):
            longest = max(longest, dfs(r, c))

    return longest

