def update_plant_heights(arr, k):
    """
    Updates the heights of plants over k days. Each day:
    - Plants at odd indices (1, 3, 5, ...) increase by 1
    - Plants at even indices (0, 2, 4, ...) decrease by 1

    :param arr: List[int] representing the heights of the plants
    :param k: int representing the number of days to update the heights
    :return: List[int] representing the final heights of the plants
    """
    for _ in range(k):
        for i in range(len(arr)):
            if i % 2 == 0:
                arr[i] -= 1
            else:
                arr[i] += 1

    return arr

