def change(amount, coins):
    """
    Returns the number of combinations that make up the amount using the given coins.
    """
    dp = [0] * (amount + 1)
    dp[0] = 1  # There's one way to make amount 0, which is using no coins

    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] += dp[x - coin]

    return dp[amount]

