def pacificAtlantic(heights):
    if not heights:
        return []

    m, n = len(heights), len(heights[0])
    pacific = [[False] * n for _ in range(m)]
    atlantic = [[False] * n for _ in range(m)]

    def dfs(x, y, ocean):
        ocean[x][y] = True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not ocean[nx][ny] and heights[nx][ny] >= heights[x][y]:
                dfs(nx, ny, ocean)

    for i in range(m):
        dfs(i, 0, pacific)
        dfs(i, n-1, atlantic)

    for j in range(n):
        dfs(0, j, pacific)
        dfs(m-1, j, atlantic)

    result = []

    for i in range(m):
        for j in range(n):
            if pacific[i][j] and atlantic[i][j]:
                result.append([i, j])

    return result

def shortest_string_length(s):
    """
    Returns the length of the shortest string that can be obtained by removing all
    occurrences of one character from the input string.
    """
    if not s:
        return 0

    min_length = len(s)

    for char in set(s):
        new_length = len(s) - s.count(char)
        if new_length < min_length:
            min_length = new_length

    return min_length

