from functools import cmp_to_key

def largest_possible_integer(inputArray):
    def compare(x, y):
        # Compare two elements as per the custom comparison logic
        if x + y > y + x:
            return -1
        elif x + y < y + x:
            return 1
        else:
            return 0

    # Convert integer array to string array for easier manipulation
    inputArray = list(map(str, inputArray))

    # Sort using the custom comparator
    inputArray.sort(key=cmp_to_key(compare))

    # Join the sorted array into a single string
    result = ''.join(inputArray)

    # Special case: if the result is all zeros, return '0' instead of '000...'
    if result[0] == '0':
        return '0'
    else:
        return result

def find_pair_with_sum(arr, x):
    """
    Returns the indices of two distinct elements in the array such that their sum equals x,
    or -1 if no such pair exists.
    """
    # Dictionary to store the value to index mapping
    value_to_index = {}

    for i, num in enumerate(arr):
        # Calculate the complement that would add up to x
        complement = x - num
        if complement in value_to_index:
            # Return the indices in ascending order
            return (value_to_index[complement], i) if value_to_index[complement] < i else (i, value_to_index[complement])
        value_to_index[num] = i

    return -1

