def product_except_self(nums, k):
    """
    Returns an array 'result' where each element at index 'i' is the product of 
    all elements in 'nums' except nums[i], and ensures the sum of all elements 
    in 'result' is less than or equal to 'k'.

    If there is no such possible 'result' array, returns an empty array.
    """
    length = len(nums)
    if length == 0:
        return []

    left_products = [1] * length
    right_products = [1] * length
    result = [0] * length

    for i in range(1, length):
        left_products[i] = left_products[i - 1] * nums[i - 1]

    for i in range(length - 2, -1, -1):
        right_products[i] = right_products[i + 1] * nums[i + 1]

    for i in range(length):
        result[i] = left_products[i] * right_products[i]

    if sum(result) > k:
        return []
    else:
        return result

