def find_min_non_negative_and_max(nums):
    """
    Returns an array of length 2 where the first element is the minimum non-negative number
    and the second element is the maximum number from the list.
    If there is no non-negative number in the list, the first element is -1.
    If there is no maximum number in the list, the second element is -1.
    """
    min_non_negative = float('inf')
    max_num = float('-inf')

    for num in nums:
        if num >= 0 and num < min_non_negative:
            min_non_negative = num
        if num > max_num:
            max_num = num

    if min_non_negative == float('inf'):
        min_non_negative = -1

    if max_num == float('-inf'):
        max_num = -1

    return [min_non_negative, max_num]

