from typing import List

def maxDistance(arr: List[int]) -> int:
    max_dist = -1
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] <= arr[j]:
                max_dist = max(max_dist, j - i)
    return max_dist

