def count_pairs_with_sum(numbers, targetSum):
    """
    Returns the number of unique pairs (i, j) such that numbers[i] + numbers[j] == targetSum and i != j.
    """
    seen = {}
    count = 0

    for num in numbers:
        complement = targetSum - num
        if complement in seen:
            count += seen[complement]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return count

