def can_transform(s1, s2):
    """
    Determine if s1 can be transformed into s2 by replacing characters with 
    characters that appear earlier in the alphabet.
    """
    for c1, c2 in zip(s1, s2):
        if c1 < c2:
            return False
    return True

def increasingTriplet(nums):
    """
    Returns True if there exists a triplet (i, j, k) such that
    0 <= i < j < k < len(nums) and nums[i] < nums[j] < nums[k].
    Otherwise, returns False.
    """
    if len(nums) < 3:
        return False

    first = second = float('inf')

    for n in nums:
        if n <= first:
            first = n
        elif n <= second:
            second = n
        else:
            return True

    return False

def min_operations_to_avoid_consecutive_duplicates(s):
    """
    Returns the minimum number of operations required to convert the string s into a string
    that contains no consecutive duplicate characters.
    """
    if not s:
        return 0

    operations = 0
    prev_char = s[0]

    for i in range(1, len(s)):
        if s[i] == prev_char:
            operations += 1
        else:
            prev_char = s[i]

    return operations

