from collections import Counter

def least_interval(tasks, n):
    """
    Returns the minimum number of time units required to complete all tasks
    following the given cooldown period.
    """
    if n == 0:
        return len(tasks)

    task_counts = Counter(tasks)
    max_freq = max(task_counts.values())

    max_freq_tasks = sum(1 for task in task_counts if task_counts[task] == max_freq)

    intervals = (max_freq - 1) * (n + 1) + max_freq_tasks
    return max(intervals, len(tasks))

