def split_string(s, k):
    """
    Splits the string s into as many parts as necessary so that each
    part is a substring of length k, while ensuring that each character
    appears in at most one of the created substrings.

    If such a split is impossible, return an empty array.
    """
    if k <= 0:
        return []

    # Count the frequency of each character
    char_counts = {}
    for char in s:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # Check if any character appears more times than allowed
    for count in char_counts.values():
        if count > 1:
            return []

    # Arrange the characters in lexicographic order
    chars_sorted = sorted(s)

    # Split the characters into parts of length k
    result = []
    i = 0
    while i < len(chars_sorted):
        result.append(''.join(chars_sorted[i:i + k]))
        i += k

    return result

