def min_removal_to_meet_condition(s, k):
    if k < 2:
        return -1
    n = len(s)

    if n == 0:
        return 0

    def helper(substr, k):
        counter = {}
        for char in substr:
            if char in counter:
                counter[char] += 1
            else:
                counter[char] = 1
        return len(counter)

    min_removal = n

    for i in range(n - k + 1):
        substr = s[i:i + k]
        distinct_chars_count = helper(substr, k)

        if distinct_chars_count <= 2:
            return 0

        j = 0
        while j < n:
            temp = s[:j] + s[j + 1:]
            temp_distinct_count = helper(temp[:k], k)
            if temp_distinct_count <= 2:
                min_removal = min(min_removal, 1 + min_removal_to_meet_condition(temp, k))
            j += 1

    return min_removal if min_removal != n else -1

