def find_substring_indices(s, words):
    """
    Returns a list of all starting indices of words' concatenations in s.
    """
    if not s or not words or not words[0]:
        return []

    word_length = len(words[0])
    num_words = len(words)
    substring_length = word_length * num_words
    word_count = {word: words.count(word) for word in words}
    result_indices = []

    for i in range(len(s) - substring_length + 1):
        seen = {}
        for j in range(num_words):
            start_index = i + j * word_length
            word = s[start_index:start_index + word_length]
            if word not in word_count:
                break
            seen[word] = seen.get(word, 0) + 1
            if seen[word] > word_count[word]:
                break
        else:
            result_indices.append(i)

    return result_indices

