def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def prime_divisors(num):
    """Return an array of unique prime divisors of num sorted in ascending order."""
    if num <= 1:
        return []

    primes = []
    for i in range(2, num + 1):
        if num % i == 0 and is_prime(i):
            primes.append(i)

    return primes

