def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in the unsorted array of integers.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)  # dp[i] will be the length of longest increasing subsequence ending at index i

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

