def knightProbability(N, k, r, c):
    """
    Return the probability that the knight remains on the board after making k moves.
    """
    directions = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                  (1, 2), (1, -2), (-1, 2), (-1, -2)]

    dp = [[[0] * N for _ in range(N)] for _ in range(k+1)]

    dp[0][r][c] = 1

    for step in range(1, k+1):
        for i in range(N):
            for j in range(N):
                for dr, dc in directions:
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < N and 0 <= nj < N:
                        dp[step][i][j] += dp[step-1][ni][nj] / 8.0

    probability = 0
    for i in range(N):
        for j in range(N):
            probability += dp[k][i][j]

    return probability

