def three_sum_closest(arr, target):
    """
    Given a list of n unique integers arr and an integer target, 
    return the sum of the three integers such that their sum is closest to target.
    """
    arr.sort()
    closest_sum = float('inf')
    n = len(arr)

    for i in range(n - 2):
        left, right = i + 1, n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if abs(current_sum - target) < abs(closest_sum - target):
                closest_sum = current_sum

            if current_sum < target:
                left += 1
            elif current_sum > target:
                right -= 1
            else:
                return current_sum

    return closest_sum

