def can_partition_k_subsets(arr, k):
    """
    Determines whether the array can be partitioned into k subsets with equal sum.

    Parameters:
    arr (List[int]): The array of non-negative integers.
    k (int): The number of subsets.

    Returns:
    bool: True if the array can be partitioned into k subsets with equal sum, False otherwise.
    """
    total_sum = sum(arr)
    target_sum = total_sum // k

    if total_sum % k != 0:
        return False

    arr.sort(reverse=True)
    used = [False] * len(arr)

    def can_partition(start_index, needed_subsets, current_sum):
        if needed_subsets == 1:
            return True
        if current_sum == target_sum:
            return can_partition(0, needed_subsets - 1, 0)
        for i in range(start_index, len(arr)):
            if not used[i] and current_sum + arr[i] <= target_sum:
                used[i] = True
                if can_partition(i + 1, needed_subsets, current_sum + arr[i]):
                    return True
                used[i] = False
        return False

    return can_partition(0, k, 0)

