def longest_unique_substring_length(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    max_length = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = i
        max_length = max(max_length, i - start + 1)

    return max_length

def judgeCircle(moves):
    """
    Determines if the sequence of moves returns the robot to its original starting position.

    Args:
    moves (str): A string of moves where 'L' means left, 'R' means right, 'U' means up, and 'D' means down.

    Returns:
    bool: True if the sequence of moves returns the robot to the original starting position, otherwise False.
    """
    horizontal, vertical = 0, 0
    for move in moves:
        if move == 'L':
            horizontal -= 1
        elif move == 'R':
            horizontal += 1
        elif move == 'U':
            vertical += 1
        elif move == 'D':
            vertical -= 1
    return horizontal == 0 and vertical == 0

