def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from the top-left to the bottom-right of the grid,
    taking into account the obstacles present in the grid.
    """
    m = len(grid)
    n = len(grid[0])

    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    dp = [[0]*n for _ in range(m)]

    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

def num_cells_water_accumulate(grid):
    from collections import deque

    def bfs(start_cells):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        q = deque(start_cells)
        seen = set(start_cells)
        while q:
            x, y = q.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in seen and grid[nx][ny] >= grid[x][y]:
                    q.append((nx, ny))
                    seen.add((nx, ny))
        return seen

    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    pacific_start = [(i, 0) for i in range(m)] + [(0, j) for j in range(n)]
    atlantic_start = [(i, n - 1) for i in range(m)] + [(m - 1, j) for j in range(n)]

    pacific_reachable = bfs(pacific_start)
    atlantic_reachable = bfs(atlantic_start)

    water_accumulate_cells = pacific_reachable & atlantic_reachable
    return len(water_accumulate_cells)

def splitArray(nums, k):
    def is_valid(mid):
        subarray_count = 1
        current_sum = 0
        for num in nums:
            if current_sum + num > mid:
                subarray_count += 1
                current_sum = num
                if subarray_count > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if is_valid(mid):
            right = mid
        else:
            left = mid + 1

    return left

