def minimize_max_books(nums, m):
    def can_partition(max_books):
        current_sum = 0
        boxes = 1

        for num in nums:
            if current_sum + num > max_books:
                boxes += 1
                current_sum = num
                if boxes > m:
                    return False
            else:
                current_sum += num
        return True

    low, high = max(nums), sum(nums)
    while low < high:
        mid = (low + high) // 2
        if can_partition(mid):
            high = mid
        else:
            low = mid + 1

    return low

