def min_operations_to_k_distinct_characters(s, k):
    from collections import Counter

    if k >= len(set(s)):
        return 0

    char_freq = Counter(s)
    char_freq_values = sorted(char_freq.values(), reverse=True)

    num_operations = 0
    while len(char_freq_values) > k:
        num_operations += char_freq_values.pop()

    return num_operations

