def min_height_to_cut(heights, target):
    def wood_collected(cut_height):
        return sum(max(0, height - cut_height) for height in heights)

    if not heights:
        return -1

    left, right = 0, max(heights)
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if wood_collected(mid) >= target:
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

