from collections import Counter
import heapq

def least_interval(tasks, k):
    """
    Returns the minimum number of units of time to finish all tasks with a cooldown period of k.
    """
    if k == 0:
        return len(tasks)

    # Count the frequency of each task
    task_counts = Counter(tasks)

    # Use a max heap to store tasks based on their frequency
    max_heap = [-cnt for cnt in task_counts.values()]
    heapq.heapify(max_heap)

    time = 0
    while max_heap:
        temp = []
        for _ in range(k + 1):
            if max_heap:
                cnt = heapq.heappop(max_heap)
                if cnt < -1:
                    temp.append(cnt + 1)
            time += 1
            if not max_heap and not temp:
                break

        for item in temp:
            heapq.heappush(max_heap, item)

    return time

