def maxValue(grid):
    """
    Returns the maximum sum of numbers that the robot can collect by the time it reaches the bottom-right cell.

    :param grid: List[List[int]] - 2D grid of non-negative integers
    :return: int - maximum sum of numbers
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]

    for j in range(1, n):
        grid[0][j] += grid[0][j - 1]

    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += max(grid[i - 1][j], grid[i][j - 1])

    return grid[m - 1][n - 1]

