def shortest_substring_containing_patterns(t, patterns):
    """
    Returns the length of the shortest substring of `t` containing all strings in `patterns`.
    If no such substring exists, return -1.
    """
    from collections import defaultdict

    def contains_all_patterns(substring, patterns):
        for pattern in patterns:
            if pattern not in substring:
                return False
        return True

    n = len(t)
    min_length = float('inf')

    # Use sliding window technique to find the shortest substring containing all patterns
    for start in range(n):
        for end in range(start + 1, n + 1):
            if contains_all_patterns(t[start:end], patterns):
                min_length = min(min_length, end - start)

    return min_length if min_length != float('inf') else -1

def is_match(s, p):
    """
    Returns true if the string s matches the pattern p, otherwise false.
    The pattern can include the special character '*' which means zero or more of the preceding element.
    """
    # Base conditions
    if not p:
        return not s

    # Check if the first character of the string matches the first character of the pattern or if the first character
    # of the pattern is '.'
    first_match = bool(s) and p[0] in {s[0], '.'}

    # Handle the '*' in the pattern
    if len(p) >= 2 and p[1] == '*':
        # Two cases:
        # 1. We ignore the current pattern character and the '*' (this is the expression is_match(s, p[2:]))
        # 2. The current pattern character matches the first character of the string and we check the rest of the string
        return is_match(s, p[2:]) or (first_match and is_match(s[1:], p))
    else:
        # Simple case: first characters match and the rest of the string must match the rest of the pattern
        return first_match and is_match(s[1:], p[1:])

