def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    max_length = 0

    for right, char in enumerate(s):
        if char in char_map:
            left = max(left, char_map[char] + 1)
        char_map[char] = right
        max_length = max(max_length, right - left + 1)

    return max_length

def longest_contiguous_subarray(nums):
    """
    Returns the length of the longest contiguous subarray that contains only one unique integer.
    """
    max_len = 0
    current_len = 1

    if not nums:
        return 0

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            current_len += 1
        else:
            max_len = max(max_len, current_len)
            current_len = 1

    max_len = max(max_len, current_len)
    return max_len

def peak_index_in_mountain_array(arr):
    """
    Returns the peak index of the mountain array. If the array is not a mountain array, return -1.
    """
    if len(arr) < 3:
        return -1

    for i in range(1, len(arr) - 1):
        if arr[i - 1] < arr[i] > arr[i + 1]:
            return i

    return -1

def max_length_monotonic_subarray(nums, k):
    def is_monotonic(array):
        increasing = decreasing = True
        for i in range(1, len(array)):
            if array[i] > array[i-1]:
                decreasing = False
            if array[i] < array[i-1]:
                increasing = False
        return increasing or decreasing

    max_length = 0
    n = len(nums)
    for i in range(n):
        unique_elements = set()
        for j in range(i, n):
            unique_elements.add(nums[j])
            if len(unique_elements) > k:
                break
            if len(unique_elements) == k and is_monotonic(nums[i:j+1]):
                max_length = max(max_length, j - i + 1)
    return max_length

