def count_visible_buildings(heights):
    """
    Returns the number of buildings that can be seen from the left side.
    """
    if not heights:
        return 0

    visible_count = 1  # The first building is always visible
    max_height = heights[0]

    for height in heights[1:]:
        if height > max_height:
            visible_count += 1
            max_height = height

    return visible_count

