solution:
def splitArray(arr, k):
    def canSplit(max_sum):
        current_sum = 0
        subarrays = 1

        for num in arr:
            if current_sum + num > max_sum:
                subarrays += 1
                current_sum = num
                if subarrays > k:
                    return False
            else:
                current_sum += num

        return True

    if k > len(arr):
        return -1

    left, right = max(arr), sum(arr)

    while left < right:
        mid = (left + right) // 2
        if canSplit(mid):
            right = mid
        else:
            left = mid + 1

    return left

