def has_three_indices_with_product(arr, target):
    """
    Determines if there are three distinct indices i, j, k in the array such that
    the product of the integers at these indices equals the target integer.

    :param arr: List of integers
    :param target: Target integer
    :return: True if such indices exist, otherwise False
    """
    n = len(arr)
    if n < 3:
        return False

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] * arr[j] * arr[k] == target:
                    return True
    return False

