def max_distinct_elements(nums, k):
    """
    Returns the maximum number of distinct elements that can be selected 
    from nums such that their sum is less than or equal to k.
    """
    nums = list(set(nums))  # get unique elements
    nums.sort()             # sort elements to pick the smallest ones first
    sum_of_selected = 0
    selected_elements = []

    for num in nums:
        if sum_of_selected + num <= k:
            sum_of_selected += num
            selected_elements.append(num)
        else:
            break

    return len(selected_elements)

