def minimizeMaxSum(arr, m):
    def valid(mid):
        current_sum = 0
        count = 1
        for num in arr:
            if current_sum + num > mid:
                count += 1
                current_sum = num
                if count > m:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(arr), sum(arr)
    while left < right:
        mid = (left + right) // 2
        if valid(mid):
            right = mid
        else:
            left = mid + 1
    return left

