def maxProfit(prices):
    """
    Returns the maximum profit that can be achieved from a single buy and sell of a stock.
    If no profit can be achieved, returns 0.
    """
    if not prices or len(prices) == 1:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices[1:]:
        profit = price - min_price
        if profit > max_profit:
            max_profit = profit
        if price < min_price:
            min_price = price

    return max_profit

