def fillLakes(grid):
    """
    Fills all lakes in the given 2D grid with '1's, and returns the count of lakes filled.
    """
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != 0:
            return
        grid[x][y] = -1  # Temporarily mark as visited
        dfs(x+1, y)
        dfs(x-1, y)
        dfs(x, y+1)
        dfs(x, y-1)

    # Mark boundary-connected '0's so they're not considered lakes
    for i in range(m):
        if grid[i][0] == 0:
            dfs(i, 0)
        if grid[i][n-1] == 0:
            dfs(i, n-1)
    for j in range(n):
        if grid[0][j] == 0:
            dfs(0, j)
        if grid[m-1][j] == 0:
            dfs(m-1, j)

    # Now process actual lakes
    def fill(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != 0:
            return
        grid[x][y] = 1
        fill(x+1, y)
        fill(x-1, y)
        fill(x, y+1)
        fill(x, y-1)

    lake_count = 0
    for i in range(1, m-1):
        for j in range(1, n-1):
            if grid[i][j] == 0:
                fill(i, j)
                lake_count += 1

    # Clean up visited marks (-1 to 0)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:
                grid[i][j] = 0

    return lake_count

