def is_word_square(words):
    """
    Returns True if the list of words forms a word square.
    A word square means that the list of words and its transpose have the same words.
    """
    n = len(words)
    for i in range(n):
        for j in range(len(words[i])):
            if j >= n or i >= len(words[j]) or words[i][j] != words[j][i]:
                return False
    return True

