def removeKDuplicates(s, k):
    """
    Removes k adjacent and equal letters from the string s repeatedly 
    until no more k duplicates are present.

    :param s: string of lowercase letters
    :param k: number of adjacent equal letters to remove
    :return: the final string after all k duplicate removals
    """
    stack = []

    for char in s:
        if stack and stack[-1][0] == char:
            if stack[-1][1] == k-1:
                stack.pop()
            else:
                stack[-1][1] += 1
        else:
            stack.append([char, 1])

    result = ""
    for char, count in stack:
        result += char * count

    return result

