def min_swaps(s: str) -> int:
    """
    Returns the minimum number of swaps required to make sure no two adjacent characters
    in the string s are the same. If it is impossible, returns -1.
    """
    n = len(s)
    if n == 1:
        return 0

    # Count occurrences of 'a' and 'b'
    count_a, count_b = s.count('a'), s.count('b')

    # Check if it is possible to rearrange the string
    if abs(count_a - count_b) > 1:
        return -1

    # Function to count swaps needed for a pattern
    def swaps_needed(pattern):
        swaps = 0
        for i in range(n):
            if s[i] != pattern[i]:
                swaps += 1
        return swaps // 2  # Each swap fixes two wrong positions

    # Create two possible patterns
    pattern1 = ''.join(['ab'[(i % 2)] for i in range(n)])
    pattern2 = ''.join(['ba'[(i % 2)] for i in range(n)])

    if count_a == count_b:  # Both patterns are valid
        return min(swaps_needed(pattern1), swaps_needed(pattern2))
    elif count_a > count_b:  # Only pattern1 is valid
        return swaps_needed(pattern1)
    else:  # Only pattern2 is valid
        return swaps_needed(pattern2)

