def longest_increasing_subsequence_length(s):
    """
    Finds the length of the longest increasing subsequence in a given string s.
    """
    if not s:
        return 0

    # Initialize an array to store the length of the longest increasing subsequence ending at each character
    dp = [1] * len(s)

    # Compute lengths of all increasing subsequences
    for i in range(1, len(s)):
        for j in range(i):
            if s[i] > s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in dp array
    return max(dp)

def minRemoveToMakeValid(s: str) -> str:
    """
    This function returns a balanced string by removing the minimum number of brackets.
    """
    open_count = 0
    result = []

    # First pass to remove invalid ')'
    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count == 0:
                continue
            open_count -= 1
        result.append(char)

    s = ''.join(result)
    result = []
    open_count = 0

    # Second pass to remove invalid '('
    for char in reversed(s):
        if char == ')':
            open_count += 1
        elif char == '(':
            if open_count == 0:
                continue
            open_count -= 1
        result.append(char)

    return ''.join(reversed(result))

