def longest_subarray_with_sum_k(arr, k):
    """
    Returns the length of the longest subarray with sum equal to k.

    :param arr: List[int], the list of integers
    :param k: int, the target sum
    :return: int, the length of the longest subarray with sum k
    """
    sum_indices = {}
    current_sum = 0
    max_length = 0

    for i in range(len(arr)):
        current_sum += arr[i]

        if current_sum == k:
            max_length = i + 1

        if current_sum - k in sum_indices:
            max_length = max(max_length, i - sum_indices[current_sum - k])

        if current_sum not in sum_indices:
            sum_indices[current_sum] = i

    return max_length

def is_one_char_diff(word1, word2):
    """
    Helper function to check if two words have exactly one character different.
    """
    diff_count = 0
    for c1, c2 in zip(word1, word2):
        if c1 != c2:
            diff_count += 1
            if diff_count > 1:
                return False
    return diff_count == 1

def rearrange_words(words):
    from itertools import permutations

    for perm in permutations(words):
        if all(is_one_char_diff(perm[i], perm[i+1]) for i in range(len(perm) - 1)):
            return True
    return False

