def max_area_of_island(grid):
    """
    Returns the maximum area of an island in the grid. If there is no island, returns 0.
    An island is formed by a group of connected black cells (1s) using 4-directional adjacency.
    """
    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return 0
        grid[i][j] = 0  # Mark the cell as visited
        return 1 + dfs(i + 1, j) + dfs(i - 1, j) + dfs(i, j + 1) + dfs(i, j - 1)

    max_area = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                max_area = max(max_area, dfs(i, j))

    return max_area

def longest_consecutive_subsequence_length(A):
    if not A:
        return 0

    num_set = set(A)
    longest_streak = 0

    for num in num_set:
        if num - 1 not in num_set:
            streak = 1
            current_num = num

            while current_num + 1 in num_set:
                current_num += 1
                streak += 1

            longest_streak = max(longest_streak, streak)

    return longest_streak

