def maxSubArray(nums):
    """
    This function takes a list of integers and returns the maximum possible sum of a contiguous subarray.
    """
    if not nums:
        return 0

    max_current = max_global = nums[0]

    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

