def kth_smallest_absolute_difference(nums, k):
    """
    Returns the k-th smallest absolute difference between any two elements in nums.
    """
    nums.sort()
    n = len(nums)

    def count_pairs(mid):
        count, j = 0, 1
        for i in range(n):
            while j < n and nums[j] - nums[i] <= mid:
                j += 1
            count += (j - i - 1)
        return count

    left, right = 0, nums[-1] - nums[0]
    while left < right:
        mid = (left + right) // 2
        if count_pairs(mid) < k:
            left = mid + 1
        else:
            right = mid
    return left

