def adjust_grades(grades):
    """
    Adjust the grades according to the following rules:
    - If the grade is less than 40, leave it unchanged.
    - If the grade is a passing grade (i.e., 40 or more),
      round it up to the nearest multiple of 5 if the difference
      between the grade and the next multiple of 5 is less than 3.
    """
    adjusted_grades = []
    for grade in grades:
        if grade < 40:
            adjusted_grades.append(grade)
        else:
            next_multiple_of_5 = (grade + 4) // 5 * 5
            if next_multiple_of_5 - grade < 3:
                adjusted_grades.append(next_multiple_of_5)
            else:
                adjusted_grades.append(grade)
    return adjusted_grades

