def find_missing_positive(nums):
    """
    Returns the smallest positive integer that is missing from the sorted array nums.
    """
    # Since nums is sorted, we iterate over the range 1 to infinity until we find a missing integer
    missing = 1
    for num in nums:
        if num > 0:
            if num == missing:
                missing += 1
            elif num > missing:
                break
    return missing

