def find_distance_to_ceo(employeeIDs, managers):
    """
    Returns a dictionary where the keys are the employee IDs and the values 
    are their respective distances to the CEO.
    """
    distance_to_ceo = {}

    # Helper function to find the distance of a given employee to the CEO.
    def get_distance(employee):
        if employee not in distance_to_ceo:
            manager = managers[employeeIDs.index(employee)]
            if manager == -1:
                distance_to_ceo[employee] = 0
            else:
                distance_to_ceo[employee] = 1 + get_distance(manager)
        return distance_to_ceo[employee]

    for emp in employeeIDs:
        get_distance(emp)

    return distance_to_ceo

