def calculate_work_times(logs):
    """
    Calculate the total time spent on each work identified by workId.

    Args:
    logs (list): List of log strings in the format "{workId}:startOrEnd:timestamp".

    Returns:
    dict: A dictionary with workId as keys and total time spent on that work in milliseconds as values.
    """
    work_times = {}
    active_work = {}

    for log in logs:
        workId, event, timestamp = log.split(':')
        timestamp = int(timestamp)

        if event == "start":
            if workId in active_work:
                # Overlapping start for this workId, ignore it
                del active_work[workId]
            else:
                active_work[workId] = timestamp

        elif event == "end":
            if workId in active_work:
                start_time = active_work[workId]
                elapsed_time = timestamp - start_time
                if workId in work_times:
                    work_times[workId] += elapsed_time
                else:
                    work_times[workId] = elapsed_time
                del active_work[workId]

    # If there are any active work that hasn't ended, they are ignored.
    return work_times

def checkValidString(s):
    """
    Check if the string with '(', ')', and '*' is valid.

    Args:
    s (str): Input string containing '(', ')', and '*'

    Returns:
    bool: True if the string is valid, False otherwise
    """
    left_balance = 0
    right_balance = 0

    for char in s:
        if char == '(' or char == '*':
            left_balance += 1
        else:
            left_balance -= 1

        if left_balance < 0:
            return False

    for char in reversed(s):
        if char == ')' or char == '*':
            right_balance += 1
        else:
            right_balance -= 1

        if right_balance < 0:
            return False

    return True

