import heapq

def minTimeToCompleteTasks(time, workers):
    if not time or not workers:
        return 0

    n = len(time)
    m = len(workers)

    task_queue = []
    for t in time:
        heapq.heappush(task_queue, -t)

    worker_queue = [0] * m

    while task_queue:
        longest_task = -heapq.heappop(task_queue)
        min_loaded_worker = heapq.heappop(worker_queue)
        min_loaded_worker += longest_task
        heapq.heappush(worker_queue, min_loaded_worker)

    return max(worker_queue)

