def tic_tac_toe_winner(matrix):
    """
    Determines the winner of a Tic-Tac-Toe game from a n x n board.
    Returns 'X' if player X wins, 'O' if player O wins, and None if there is no winner.
    """
    n = len(matrix)

    # Check rows
    for row in matrix:
        if row[0] != '-' and all(cell == row[0] for cell in row):
            return row[0]

    # Check columns
    for col in range(n):
        if matrix[0][col] != '-' and all(matrix[row][col] == matrix[0][col] for row in range(n)):
            return matrix[0][col]

    # Check main diagonal
    if matrix[0][0] != '-' and all(matrix[i][i] == matrix[0][0] for i in range(n)):
        return matrix[0][0]

    # Check secondary diagonal
    if matrix[0][n-1] != '-' and all(matrix[i][n-1-i] == matrix[0][n-1] for i in range(n)):
        return matrix[0][n-1]

    return None

def largest_square(grid):
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    max_square_size = 0

    # Create a DP table initialized to 0
    dp = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_square_size = max(max_square_size, dp[i][j])

    # Return the size of the largest square, which is the side length squared
    return max_square_size * max_square_size

