import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Push all the border cells into the priority queue
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m-1 or j == 0 or j == n-1:
                heapq.heappush(heap, (heightMap[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    max_trapped, min_boundary_height = 0, 0

    while heap:
        height, x, y = heapq.heappop(heap)
        min_boundary_height = max(min_boundary_height, height)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                if heightMap[nx][ny] < min_boundary_height:
                    max_trapped += min_boundary_height - heightMap[nx][ny]
                heapq.heappush(heap, (heightMap[nx][ny], nx, ny))

    return max_trapped

def highest_peak(grid):
    """
    Finds and returns the height of the highest peak in the given grid.
    A peak is defined as a cell that is taller than all of its adjacent cells (north, south, east, west).
    """
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])
    highest = -1

    def is_peak(i, j):
        current = grid[i][j]
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and current <= grid[ni][nj]:
                return False
        return True

    for i in range(1, m - 1):
        for j in range(1, n - 1):
            if is_peak(i, j):
                highest = max(highest, grid[i][j])

    return highest

