def has_pair_with_sum(arr, k):
    """
    Returns True if there are two integers in the array whose sum is exactly k. Otherwise, returns False.
    """
    seen = set()
    for num in arr:
        if k - num in seen:
            return True
        seen.add(num)
    return False

