def max_connected_land_components(grid):
    """
    Returns the maximum number of connected land components after shuffling the matrix.
    """
    m, n = len(grid), len(grid[0])
    land_cells = sum(cell for row in grid for cell in row)

    def dfs(x, y, visited):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and (nx * n + ny) < land_cells:
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    visited = [[False] * n for _ in range(m)]
    components = 0
    for i in range(m):
        for j in range(n):
            if not visited[i][j] and (i * n + j) < land_cells:
                visited[i][j] = True
                dfs(i, j, visited)
                components += 1

    return components

