from typing import List

def longest_subarray_with_sum_k(arr: List[int], k: int) -> int:
    """
    Returns the length of the longest subarray with a sum equal to k.
    If there are no such subarrays, returns 0.
    """
    sum_map = {}
    current_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        current_sum += num

        if current_sum == k:
            max_length = i + 1

        if current_sum - k in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

