from typing import List

def countSubarrays(nums: List[int], k: int) -> int:
    count = 0
    current_sum = 0
    sum_count_dict = {0: 1}

    for num in nums:
        current_sum += num

        if (current_sum - k) in sum_count_dict:
            count += sum_count_dict[current_sum - k]

        if current_sum in sum_count_dict:
            sum_count_dict[current_sum] += 1
        else:
            sum_count_dict[current_sum] = 1

    return count

