def longest_subarray_with_k_odds(nums, k):
    """
    Returns the length of the longest subarray with at most k odd numbers.
    """
    left = 0
    odd_count = 0
    max_len = 0

    for right in range(len(nums)):
        if nums[right] % 2 != 0:
            odd_count += 1

        while odd_count > k:
            if nums[left] % 2 != 0:
                odd_count -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

