def highest_scores_of_nearest_k_competitors(scores, K):
    n = len(scores)
    highest_scores = []

    for i in range(n):
        # Determine the bounds for K competitors on either side
        start = max(0, i - K)
        end = min(n, i + K + 1)

        # Exclude the current participant's score
        competitors_scores = scores[start:i] + scores[i+1:end]

        # Find the highest score among the competitors
        if competitors_scores:
            highest_score = max(competitors_scores)
        else:
            highest_score = None

        highest_scores.append(highest_score)

    return highest_scores

