def count_balanced_subarrays(arr, k):
    """
    Returns the number of balanced subarrays in the given array.

    A balanced subarray has the difference between its maximum
    and minimum elements less than or equal to k.
    """
    def is_balanced_subarray(subarray):
        return max(subarray) - min(subarray) <= k

    n = len(arr)
    count = 0

    for i in range(n):
        for j in range(i, n):
            if is_balanced_subarray(arr[i:j+1]):
                count += 1

    return count

