from collections import deque

def walls_and_gates(rooms):
    """
    Fills each empty room with the distance to its nearest gate. 
    If it is impossible to reach a gate, it remains filled with inf.
    """
    if not rooms or not rooms[0]:
        return

    m, n = len(rooms), len(rooms[0])
    queue = deque()

    # Initialize the queue with all the gates' positions
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    # Perform BFS from the gates
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < m and 0 <= new_y < n and rooms[new_x][new_y] == 2147483647:
                rooms[new_x][new_y] = rooms[x][y] + 1
                queue.append((new_x, new_y))

