def count_viewable_blocks(heights):
    """
    Returns the number of viewable blocks in the array.
    """
    n = len(heights)
    viewable_blocks = 0

    for i in range(n):
        max_so_far = heights[i]
        for j in range(i, n):
            if heights[j] > max_so_far:
                max_so_far = heights[j]
                viewable_blocks += 1
            elif heights[j] != max_so_far:
                viewable_blocks += 1

    return viewable_blocks

