def longest_non_decreasing_subsequence(nums):
    """
    Calculate the length of the longest non-decreasing subsequence in a list of integers.

    :param nums: List[int] - A list of integers.
    :return: int - Length of the longest non-decreasing subsequence.
    """

    if not nums:
        return 0

    # Initialize the dp array where dp[i] will be the length of longest non-decreasing subsequence ending at nums[i]
    dp = [1] * len(nums)

    # Fill dp array using dynamic programming
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] >= nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest non-decreasing subsequence will be the maximum value in dp array
    return max(dp)

