def largest_number_from_digits(digits):
    """
    Given a string `digits` containing only digits, return the largest number 
    that can be formed by rearranging the digits. If the input string is empty, return an empty string.
    """
    if not digits:
        return ""
    return "".join(sorted(digits, reverse=True))

def find_words(words, s):
    """
    This function finds and returns the list of words from the given list `words` that can be used to
    form the string `s` in the correct order. Each word in `words` can be used only once.

    :param words: List of unique words.
    :param s: String that is a concatenation of the words from `words`.
    :return: The list of words in the order they appear in `s`, if a solution exists; otherwise, return an empty list.
    """
    def backtrack(start, path):
        if start == len(s):
            return path
        for word in words:
            if s.startswith(word, start):
                result = backtrack(start + len(word), path + [word])
                if result:
                    return result
        return None

    result = backtrack(0, [])
    return result if result else []

