from collections import deque

def fill_grid_with_min_steps(grid):
    """
    Fills each '1' in the grid with the minimum number of steps required to reach it from the closest '0'.
    If it is impossible, fill it with -1 instead.
    """
    if not grid:
        return grid

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque()
    distances = [[float('inf')] * cols for _ in range(rows)]

    # Initialize the queue with positions of all '0's and set their distances to 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                queue.append((r, c))
                distances[r][c] = 0

    # Perform BFS from all '0's
    while queue:
        row, col = queue.popleft()
        for dr, dc in directions:
            newRow, newCol = row + dr, col + dc
            if 0 <= newRow < rows and 0 <= newCol < cols and grid[newRow][newCol] != -1:
                if distances[newRow][newCol] > distances[row][col] + 1:
                    distances[newRow][newCol] = distances[row][col] + 1
                    queue.append((newRow, newCol))

    # Update the grid
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                grid[r][c] = distances[r][c] if distances[r][c] != float('inf') else -1

    return grid

