def numIslands(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == '0' or visited[i][j]:
            return
        visited[i][j] = True
        dfs(i+1, j)
        dfs(i-1, j)
        dfs(i, j+1)
        dfs(i, j-1)

    island_count = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                dfs(i, j)
                island_count += 1

    return island_count

from collections import deque

def add_operation(s, a):
    s = list(s)
    for i in range(1, len(s), 2):
        s[i] = str((int(s[i]) + a) % 10)
    return ''.join(s)

def findLexSmallestString(s, a, b):
    visited = set()
    queue = deque([s])
    smallest = s

    while queue:
        current = queue.popleft()
        if current < smallest:
            smallest = current

        # Apply add operation
        added = add_operation(current, a)
        if added not in visited:
            visited.add(added)
            queue.append(added)

        # Apply rotate operation
        rotated = current[-b:] + current[:-b]
        if rotated not in visited:
            visited.add(rotated)
            queue.append(rotated)

    return smallest

