from typing import List

def canReachLastStep(steps: List[int]) -> bool:
    """
    Determines if a person can reach the last step from the first step given the movement constraints.

    Args:
    steps (List[int]): A list of n integers representing the heights of the steps.

    Returns:
    bool: True if the person can reach the last step, False otherwise.
    """
    n = len(steps)
    if n == 0:
        return False # No steps to move

    def can_reach(index):
        if index >= n - 1:
            return True
        if index < 0 or steps[index] >= steps[index + 1]:
            if index + 2 < n and steps[index] < steps[index + 2]:
                return can_reach(index + 2)
            return False

        return can_reach(index + 1) or (index + 2 < n and can_reach(index + 2) if steps[index] < steps[index + 2] else False)

    return can_reach(0)

