def max_points_on_line(points):
    import math

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def slope(c1, c2):
        dx = c2[0] - c1[0]
        dy = c2[1] - c1[1]
        if dx == 0:
            return 'inf'
        g = gcd(dx, dy)
        return (dy // g, dx // g)

    if not points:
        return 0

    max_points = 1

    for i in range(len(points)):
        slopes = {}
        same_point = 0
        for j in range(i + 1, len(points)):
            if points[i] == points[j]:
                same_point += 1
                continue
            s = slope(points[i], points[j])
            if s in slopes:
                slopes[s] += 1
            else:
                slopes[s] = 1

        current_max = same_point
        for count in slopes.values():
            if count + same_point > current_max:
                current_max = count + same_point

        max_points = max(max_points, current_max + 1)

    return max_points

