def minimumCost(n, connections):
    """
    Return the minimum cost to connect all cities with a path between any two cities.
    If it's not possible, return -1.
    """
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            parent[i] = find(parent, parent[i])
            return parent[i]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)

        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    connections.sort(key=lambda x: x[2])
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)

    mst_cost = 0
    edges_used = 0

    for city1, city2, cost in connections:
        if find(parent, city1) != find(parent, city2):
            union(parent, rank, city1, city2)
            mst_cost += cost
            edges_used += 1
            if edges_used == n - 1:
                return mst_cost

    return -1 if edges_used != n - 1 else mst_cost

