def longest_bounded_increasing_subsequence(height):
    """
    Returns the length of the longest increasing subsequence of height such that the
    difference between consecutive elements is bounded by 1.
    """
    if not height:
        return 0

    n = len(height)
    # dp[i] will be the length of the longest bounded subsequence ending at height[i]
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(height[i] - height[j]) <= 1 and height[i] > height[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

