def check_subarray_sum(nums, k):
    """
    Given an array of integers 'nums' and an integer 'k',
    check if there is a continuous subarray of length at least 2 that sums up to a multiple of k.
    """
    if k == 0:
        # Special case when k is 0
        for i in range(len(nums) - 1):
            if nums[i] == 0 and nums[i + 1] == 0:
                return True
        return False

    mod_dict = {0: -1}  # Dictionary to store modulus and index
    running_sum = 0

    for i in range(len(nums)):
        running_sum += nums[i]
        if k != 0:
            running_sum %= k

        if running_sum in mod_dict:
            if i - mod_dict[running_sum] > 1:
                return True
        else:
            mod_dict[running_sum] = i

    return False

def countBattleships(board):
    """
    Count the number of distinct battleships on the board.
    """
    if not board:
        return 0

    rows, columns = len(board), len(board[0])
    count = 0

    for r in range(rows):
        for c in range(columns):
            if board[r][c] == 'X':
                if (r > 0 and board[r-1][c] == 'X') or (c > 0 and board[r][c-1] == 'X'):
                    continue
                count += 1

    return count

