def can_empty_array(nums, x):
    """
    Determines if the array can be made empty by repeatedly removing a contiguous subarray whose sum is equal to x.
    """
    def can_remove_subarray(nums, x, start):
        if not nums:
            return True
        running_sum = 0
        for i in range(start, len(nums)):
            running_sum += nums[i]
            if running_sum == x:
                # Recursively check the remaining part of the array
                if can_remove_subarray(nums[i + 1:], x, 0):
                    return True
        return False

    return can_remove_subarray(nums, x, 0)

