def largest_island(grid):
    """
    Returns the size of the largest island in the given grid.
    """
    if not grid or not grid[0]: 
        return 0

    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == '0':
            return 0
        grid[x][y] = '0'  # Mark the cell as visited
        size = 1 
        size += dfs(x + 1, y)
        size += dfs(x - 1, y)
        size += dfs(x, y + 1)
        size += dfs(x, y - 1)
        return size

    max_size = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                max_size = max(max_size, dfs(i, j))

    return max_size

