def exist(board, word):
    def helper(x, y, word):
        if len(word) == 0:
            return True
        if x < 0 or x >= len(board) or y < 0 or y >= len(board[0]) or board[x][y] != word[0]:
            return False
        tmp, board[x][y] = board[x][y], '#'
        res = helper(x + 1, y, word[1:]) or helper(x - 1, y, word[1:]) or helper(x, y + 1, word[1:]) or helper(x, y - 1, word[1:])
        board[x][y] = tmp
        return res

    for i in range(len(board)):
        for j in range(len(board[0])):
            if helper(i, j, word):
                return True
    return False

