def evalRPN(tokens):
    """
    Evaluates the value of an arithmetic expression in Reverse Polish Notation (RPN).

    :param tokens: List[str] - List of strings representing the RPN expression.
    :return: int - Result of the evaluated expression.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                result = int(a / b)  # Truncate towards zero
            stack.append(result)
        else:
            stack.append(int(token))
    return stack[0]

