def count_isolated_artworks(grid):
    """
    Given a 2D binary grid representing the gallery, this function returns the
    number of isolated artworks. An artwork is isolated if it is not adjacent
    to any other artwork either horizontally or vertically.
    """
    def is_isolated(i, j):
        # Check all four possible directions for adjacency
        if i > 0 and grid[i-1][j] == 1:
            return False
        if i < len(grid) - 1 and grid[i+1][j] == 1:
            return False
        if j > 0 and grid[i][j-1] == 1:
            return False
        if j < len(grid[0]) - 1 and grid[i][j+1] == 1:
            return False
        return True

    # Initialize the count of isolated artworks
    count = 0

    # Iterate through each cell in the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1 and is_isolated(i, j):
                count += 1

    return count

def can_transform(s, t):
    """
    Determines if string s can be transformed into string t by exactly replacing
    each character once.
    """
    if len(s) != len(t):
        return False

    # Check mapping from s to t and t to s
    s_to_t = {}
    t_to_s = {}

    for sc, tc in zip(s, t):
        if sc in s_to_t:
            if s_to_t[sc] != tc:
                return False
        else:
            s_to_t[sc] = tc

        if tc in t_to_s:
            if t_to_s[tc] != sc:
                return False
        else:
            t_to_s[tc] = sc

    return True

