def count_distinct_integers(arr, k):
    """
    Returns the number of distinct integers present in all intervals of length k or more.
    """
    if not arr or k <= 0:
        return 0

    distinct_integers = set()
    n = len(arr)

    for start in range(n):
        current_set = set()
        for end in range(start, n):
            current_set.add(arr[end])
            if end - start + 1 >= k:
                distinct_integers.update(current_set)

    return len(distinct_integers)

