def max_distinct_sections(s):
    """
    Returns the maximum number of distinct contiguous sections in the given string.
    Each section is made up of one or more repeated characters.
    """
    if not s:
        return 0

    sections = 1
    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            sections += 1
    return sections

