def three_sum_exists(nums, target):
    """
    Checks if there are three distinct indices i, j, k in the array such that
    nums[i] + nums[j] + nums[k] == target.

    :param nums: List of integers
    :param target: Target integer sum
    :return: Boolean value indicating if such indices exist
    """
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] + nums[j] + nums[k] == target:
                    return True
    return False

def splitArray(nums, k):
    """
    Split the array into k contiguous subarrays such that the sum of the maximum subarray sums is minimized.
    Returns the minimized sum of the maximum subarray sums.
    """
    def can_split(nums, k, max_sum):
        current_sum = 0
        count = 1
        for num in nums:
            if current_sum + num > max_sum:
                count += 1
                current_sum = num
                if count > k:
                    return False
            else:
                current_sum += num
        return True

    low, high = max(nums), sum(nums)
    while low < high:
        mid = (low + high) // 2
        if can_split(nums, k, mid):
            high = mid
        else:
            low = mid + 1
    return low

