def rotate_matrix(matrix):
    """
    Rotates the given n x n matrix 90 degrees clockwise in-place.

    :param matrix: List of List of int, the n x n matrix to rotate
    """
    n = len(matrix)

    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(n):
        matrix[i].reverse()

