def min_add_to_make_valid(s):
    """
    Returns the minimum number of parentheses to be added to make a string s valid.
    """
    open_count = 0
    add_count = 0

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                add_count += 1

    return add_count + open_count

def maxDistToClosest(nums):
    """
    Returns the maximum distance to the nearest person for any empty seat.
    """
    max_dist = 0
    last_person = -1
    n = len(nums)

    for i in range(n):
        if nums[i] == 1:
            if last_person == -1:
                # All seats from the start are empty
                max_dist = max(max_dist, i)
            else:
                # The distance to the nearest person for seats between two people
                max_dist = max(max_dist, (i - last_person) // 2)
            last_person = i

    # All seats from the last person to the end are empty
    if nums[-1] == 0:
        max_dist = max(max_dist, n - last_person - 1)

    return max_dist

