def max_value(events):
    events.sort(key=lambda x: x[1])  # Sort by endTime
    dp = [0] * len(events)

    def binary_search(events, index):
        low, high = 0, index - 1
        while low <= high:
            mid = (low + high) // 2
            if events[mid][1] < events[index][0]:
                if events[mid + 1][1] < events[index][0]:
                    low = mid + 1
                else:
                    return mid
            else:
                high = mid - 1
        return -1

    dp[0] = events[0][2]
    for i in range(1, len(events)):
        include_value = events[i][2]
        exclude_value = dp[i - 1]
        last_non_conflict = binary_search(events, i)

        if last_non_conflict != -1:
            include_value += dp[last_non_conflict]

        dp[i] = max(include_value, exclude_value)

    return dp[-1]

