def min_swaps_to_make_valid_parentheses(s):
    """
    Calculate the minimum number of swaps required to make the parentheses sequence valid.
    """
    open_count = 0  # Number of unmatched open parentheses
    close_count = 0  # Number of unmatched close parentheses

    for ch in s:
        if ch == '(':
            open_count += 1
        else:
            if open_count > 0:
                open_count -= 1
            else:
                close_count += 1

    # Since each pair can be fixed by one swap, the number of swaps required is half of 
    # the total number of unmatched parentheses.
    return (open_count + close_count) // 2

