def average_of_k_highest(grades, k):
    """
    Returns the average of the k highest grades.
    If k is greater than or equal to the number of students, returns the average of all grades.
    """
    if not grades:
        return 0

    grades_sorted = sorted(grades, reverse=True)
    if k >= len(grades_sorted):
        return sum(grades_sorted) / len(grades_sorted)

    return sum(grades_sorted[:k]) / k

