from collections import deque

def minTotalTravelDistance(grid):
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])
    buildings = []
    obstacles = set()

    # Gather all buildings and obstacles
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                buildings.append((i, j))
            elif grid[i][j] == 2:
                obstacles.add((i, j))

    if not buildings:
        return -1

    distance_sum = [[0] * n for _ in range(m)]
    reach = [[0] * n for _ in range(m)]
    directions = [(0,1), (1,0), (0,-1), (-1,0)]

    def bfs(start_i, start_j):
        visited = [[False] * n for _ in range(m)]
        queue = deque([(start_i, start_j, 0)])
        visited[start_i][start_j] = True

        while queue:
            i, j, dist = queue.popleft()
            distance_sum[i][j] += dist
            reach[i][j] += 1

            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and grid[ni][nj] == 0:
                    visited[ni][nj] = True
                    queue.append((ni, nj, dist + 1))

    # Run BFS from each building
    for bi, bj in buildings:
        bfs(bi, bj)

    min_distance = float('inf')
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0 and reach[i][j] == len(buildings):
                min_distance = min(min_distance, distance_sum[i][j])

    return min_distance if min_distance != float('inf') else -1

def longest_palindromic_subsequence_lengths(s):
    n = len(s)
    result = [0] * n

    for i in range(n):
        subsequence = s[:i+1]
        result[i] = longest_palindromic_subsequence(subsequence)

    return result

def longest_palindromic_subsequence(subsequence):
    m = len(subsequence)
    dp = [[0] * m for _ in range(m)]

    for i in range(m):
        dp[i][i] = 1

    for length in range(2, m+1):
        for start in range(m-length+1):
            end = start + length - 1
            if subsequence[start] == subsequence[end]:
                dp[start][end] = dp[start+1][end-1] + 2
            else:
                dp[start][end] = max(dp[start][end-1], dp[start+1][end])

    return dp[0][m-1]

