def smallest_configuration(configs):
    """
    Returns the lexicographically smallest configuration string that can be formed
    by concatenating exactly one character from each string in configs.
    """
    smallest_config = []
    for characters in configs:
        smallest_char = min(characters)
        smallest_config.append(smallest_char)

    return ''.join(smallest_config)

