def firstNonRepeatingCharacter(s):
    """
    Returns the index of the first non-repeating character in the given string, 
    or -1 if there is no such character.
    """

    # Record the frequency of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate through the string and return the index of the first non-repeating character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    return -1

def lexicographically_smallest_string(s, k):
    if k == 1:
        # Generate all rotations of the string and return the lexicographically smallest one
        candidates = [s[i:] + s[:i] for i in range(len(s))]
        return min(candidates)
    else:
        # If k > 1, we can fully sort the string to get the smallest lexicographic order
        return ''.join(sorted(s))

