def max_profit(k, arr):
    n = len(arr)
    if n == 0:
        return 0

    # If k is greater than n//2, it is equivalent to unlimited transactions.
    if k >= n // 2:
        return sum(
            max(arr[i + 1] - arr[i], 0) for i in range(n - 1)
        )

    profits = [[0] * n for _ in range(k + 1)]
    for t in range(1, k + 1):
        max_diff = -arr[0]
        for d in range(1, n):
            profits[t][d] = max(profits[t][d - 1], arr[d] + max_diff)
            max_diff = max(max_diff, profits[t - 1][d] - arr[d])

    return profits[k][-1]

