def partition_labels(s):
    """
    Partition the string s into the maximum number of substrings such that no letter appears in more than one substring.

    :param s: A string consisting of lowercase English letters.
    :return: A list of substrings meeting the condition.
    """
    last_occurrence = {char: idx for idx, char in enumerate(s)}
    partitions = []
    start = end = 0

    for i, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if i == end:
            partitions.append(s[start:end + 1])
            start = i + 1

    return partitions

