def minimize_max_difference(students, k):
    """
    Returns the minimized difference between the maximum and minimum skill levels among k groups.
    """
    students.sort()

    def is_valid_max_diff(mid):
        count = 1
        min_val = students[0]
        for skill in students:
            if skill - min_val > mid:
                count += 1
                min_val = skill
        return count <= k

    low, high = 0, students[-1] - students[0]
    while low < high:
        mid = (low + high) // 2
        if is_valid_max_diff(mid):
            high = mid
        else:
            low = mid + 1

    return low

