def longest_increasing_common_subsequence(nums1, nums2):
    """
    Returns the length of the longest common subsequence that is strictly increasing in both nums1 and nums2.
    """
    n1, n2 = len(nums1), len(nums2)
    dp = [[0] * (n2+1) for _ in range(n1+1)]

    for i in range(1, n1+1):
        for j in range(1, n2+1):
            if nums1[i-1] == nums2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n1][n2]

def multiply_matrices(mat1, mat2):
    m, n = len(mat1), len(mat1[0])
    k, p = len(mat2), len(mat2[0])

    if n != k:
        return []

    # Initialize the result matrix with zeros
    result = [[0] * p for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(n):
            if mat1[i][j] != 0:
                for l in range(p):
                    result[i][l] += mat1[i][j] * mat2[j][l]

    return result

from typing import List

def combinationSum(candidates: List[int], target: int) -> List[List[int]]:
    def backtrack(start, current_combination, current_sum):
        if current_sum == target:
            result.append(list(current_combination))
            return
        if current_sum > target:
            return

        for i in range(start, len(candidates)):
            current_combination.append(candidates[i])
            backtrack(i, current_combination, current_sum + candidates[i])
            current_combination.pop()

    result = []
    candidates.sort()
    backtrack(0, [], 0)

    return result

