def count_good_sentences(sentences):
    """
    Returns the number of good sentences in the array `sentences`.
    A sentence is classified as "good" if it contains an even number of words.
    """
    def is_good(sentence):
        words = sentence.split()
        return len(words) % 2 == 0

    return sum(is_good(sentence) for sentence in sentences)

