def unique_paths_dag(n, edges, start, end):
    from collections import defaultdict, deque

    # Build the adjacency list for the DAG
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Function to perform topological sorting using Kahn's Algorithm
    def topological_sort():
        in_degree = [0] * n
        for u in graph:
            for v in graph[u]:
                in_degree[v] += 1

        queue = deque([i for i in range(n) if in_degree[i] == 0])
        topo_order = []

        while queue:
            node = queue.popleft()
            topo_order.append(node)
            for neighbour in graph[node]:
                in_degree[neighbour] -= 1
                if in_degree[neighbour] == 0:
                    queue.append(neighbour)
        return topo_order

    topo_order = topological_sort()
    dp = [0] * n
    dp[start] = 1

    for node in topo_order:
        for neighbour in graph[node]:
            dp[neighbour] += dp[node]

    return dp[end]

from collections import Counter

def min_operations_to_anagram(s, t):
    """
    Returns the minimum number of operations required to make t an anagram of s.
    """
    if len(s) != len(t):
        raise ValueError("The strings s and t must be of the same length to be anagrams of each other")

    count_s = Counter(s)
    count_t = Counter(t)

    operations = 0
    for char in count_s:
        if char in count_t:
            if count_s[char] > count_t[char]:
                operations += count_s[char] - count_t[char]
        else:
            operations += count_s[char]

    return operations

