def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring in s.
    A balanced substring contains an equal number of 'a' and 'b'.
    """
    max_len = 0
    n = len(s)

    # To keep track of count differences
    count_diff = {0: -1}  # Initialize with difference 0 at index -1
    count = 0

    for i in range(n):
        if s[i] == 'a':
            count += 1
        else:
            count -= 1

        if count in count_diff:
            max_len = max(max_len, i - count_diff[count])
        else:
            count_diff[count] = i

    return max_len

def length_of_lis(nums):
    """
    Returns the length of the longest increasing subsequence in an array of integers.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

