def length_of_longest_subarray(nums):
    """
    Returns the length of the longest subarray without repeating elements.
    """
    if not nums:
        return 0

    start = maxLength = 0
    seen = {}

    for end in range(len(nums)):
        if nums[end] in seen:
            start = max(start, seen[nums[end]] + 1)
        seen[nums[end]] = end
        maxLength = max(maxLength, end - start + 1)

    return maxLength

