def find_peak_element(nums):
    """
    Finds the index of the first peak element in the given unique integer array.

    :param nums: List[int] - The list of unique integers
    :return: int - The index of the first peak element
    """
    n = len(nums)

    if n == 0:
        return -1  # Edge case for empty array, though the problem implies array is non-empty

    if n == 1:
        return 0  # Only one element is trivially a peak

    # Check the first element
    if nums[0] > nums[1]:
        return 0

    # Check the last element
    if nums[n - 1] > nums[n - 2]:
        return n - 1

    # Check remaining elements
    for i in range(1, n - 1):
        if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
            return i

    return -1  # Should not reach here if input guarantees at least one peak

