def combination_sum(n):
    """
    Returns all possible unique combinations of positive integers that sum up to n
    """
    result = []

    def backtrack(remaining, start, path):
        if remaining == 0:
            result.append(path)
            return
        for i in range(start, remaining + 1):
            backtrack(remaining - i, i, path + [i])

    backtrack(n, 1, [])
    return result

