def max_distinct_pairs(nums, k):
    nums_count = {}
    for num in nums:
        if num in nums_count:
            nums_count[num] += 1
        else:
            nums_count[num] = 1

    pairs = 0

    for num in list(nums_count.keys()):
        target = k - num
        if target in nums_count:
            if target == num:
                pairs += nums_count[num] // 2
            else:
                pairs += min(nums_count[num], nums_count[target])
            del nums_count[num]
            if target in nums_count:
                del nums_count[target]

    return pairs

