def num_partitions(s, k):
    """
    Given a string s and an integer k, partition the string into as few parts as possible 
    such that each part contains no more than k distinct characters. 
    Return the total number of parts needed.
    """
    if k == 0 or not s:
        return 0

    count = 0
    distinct_chars = set()
    for char in s:
        distinct_chars.add(char)
        if len(distinct_chars) > k:
            count += 1
            distinct_chars = {char}

    return count + 1

