def min_operations_to_transform(source, target):
    """
    Returns the minimum number of operations required to transform the source string into the target string.
    Operations allowed: insert, delete, replace.
    """
    m, n = len(source), len(target)

    # Initialize a DP array
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases for transformation from empty string to target, or source to empty string
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the DP array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1])  # Replacement

    return dp[m][n]

