def is_multiple_of_11(num):
    """
    Returns True if the large integer represented as a string 'num' is a multiple of 11, otherwise False.
    """
    odd_sum, even_sum = 0, 0
    for i, digit in enumerate(num):
        if i % 2 == 0:
            odd_sum += int(digit)
        else:
            even_sum += int(digit)

    return (odd_sum - even_sum) % 11 == 0

def count_primes(n):
    """
    Returns the number of prime numbers strictly less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes
    for start in range(2, int(n ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, n, start):
                sieve[multiple] = False

    return sum(sieve)

