def partition_labels(s):
    """
    Partitions the string such that each letter appears in at most one part 
    and returns the sizes of these parts.
    """
    last_occurrence = {char: idx for idx, char in enumerate(s)}
    result = []
    start = end = 0

    for index, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if index == end:
            result.append(end - start + 1)
            start = index + 1

    return result

