def num_shapes(grid, numShapes):
    def dfs(x, y):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == 0:
            return
        grid[x][y] = 0  # Marking the cell as visited
        # Exploring all four possible directions (up, down, left, right)
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    shape_count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                dfs(i, j)
                shape_count += 1
    return shape_count == numShapes

