from collections import deque

def min_distance_to_building(city):
    """
    Finds the minimum sum of Manhattan distances from an empty plot to all buildings in the city.
    """
    if not city or not city[0]:
        return -1

    rows, cols = len(city), len(city[0])
    buildings = [(i, j) for i in range(rows) for j in range(cols) if city[i][j] == 1]

    if not buildings:
        return -1

    def bfs(start):
        visited = set()
        queue = deque([(start, 0)])
        total_dist = 0

        while queue:
            (x, y), dist = queue.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))

            if city[x][y] == 1:
                total_dist += dist

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
                    queue.append(((nx, ny), dist + 1))

        return total_dist

    min_distance = float('inf')

    for i in range(rows):
        for j in range(cols):
            if city[i][j] == 0:
                distance = bfs((i, j))
                min_distance = min(min_distance, distance)

    return -1 if min_distance == float('inf') else min_distance

