def find_indices_with_difference(arr, x):
    """
    Returns a list of two indices [i, j] such that the absolute difference between arr[i] and arr[j] is exactly x.
    If no such pair exists, return an empty list.
    """
    if not arr or x < 0:
        return []

    value_to_indices = {}
    for index, value in enumerate(arr):
        if value in value_to_indices:
            value_to_indices[value].append(index)
        else:
            value_to_indices[value] = [index]

    for index, value in enumerate(arr):
        if value + x in value_to_indices:
            for candidate_index in value_to_indices[value + x]:
                if candidate_index != index:
                    return [index, candidate_index]
        if value - x in value_to_indices:
            for candidate_index in value_to_indices[value - x]:
                if candidate_index != index:
                    return [index, candidate_index]

    return []

def min_cut_palindrome(s):
    """
    Returns the minimum number of cuts needed to split the string into palindromic substrings.
    """
    n = len(s)
    if n <= 1:
        return 0

    # Create a DP table to check palindrome for substrings
    is_palindrome = [[False] * n for _ in range(n)]
    for i in range(n):
        is_palindrome[i][i] = True

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 2:
                is_palindrome[i][j] = (s[i] == s[j])
            else:
                is_palindrome[i][j] = (s[i] == s[j] and is_palindrome[i + 1][j - 1])

    # Create a DP array to find the minimum cuts
    cuts = [0] * n
    for i in range(n):
        if is_palindrome[0][i]:
            cuts[i] = 0
        else:
            cuts[i] = float('inf')
            for j in range(i):
                if is_palindrome[j + 1][i] and cuts[j] + 1 < cuts[i]:
                    cuts[i] = cuts[j] + 1

    return cuts[-1]

