from collections import deque

def shortest_path_binary_matrix(grid):
    n = len(grid)
    if n == 0 or grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return -1

    def in_bounds(x, y):
        return 0 <= x < n and 0 <= y < n

    # Directions for movement
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # BFS queue: (x, y, path_length, obstacle_broken)
    queue = deque([(0, 0, 1, False)])
    visited = set([(0, 0, False)])

    while queue:
        x, y, path_length, obstacle_broken = queue.popleft()

        if (x, y) == (n-1, n-1):
            return path_length

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if in_bounds(nx, ny):
                if grid[nx][ny] == 0 and (nx, ny, obstacle_broken) not in visited:
                    queue.append((nx, ny, path_length + 1, obstacle_broken))
                    visited.add((nx, ny, obstacle_broken))
                elif grid[nx][ny] == 1 and not obstacle_broken and (nx, ny, True) not in visited:
                    queue.append((nx, ny, path_length + 1, True))
                    visited.add((nx, ny, True))

    return -1

def min_toggles_to_equal_matrix(matrix):
    """
    Determine the minimum number of toggles required to make all elements in the matrix equal.
    """
    def toggle(matrix, i, j):
        """
        Toggle the element at (i, j) and its neighbors.
        """
        rows, cols = len(matrix), len(matrix[0])
        neighbors = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        matrix[i][j] ^= 1
        for di, dj in neighbors:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                matrix[ni][nj] ^= 1

    rows, cols = len(matrix), len(matrix[0])
    original_matrix = [row[:] for row in matrix]
    operations_0 = operations_1 = 0

    # Try to make all 0s
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                toggle(matrix, i, j)
                operations_0 += 1

    # Reset matrix and try to make all 1s
    matrix = [row[:] for row in original_matrix]
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 0:
                toggle(matrix, i, j)
                operations_1 += 1

    return min(operations_0, operations_1)

# Example usage
matrix = [
    [0, 0, 0],
    [1, 0, 0],
    [0, 0, 0]
]
print(min_toggles_to_equal_matrix(matrix)) # Output should be the minimum number of toggles required

