def find_fixed_point(arr):
    """
    Finds the fixed point in the array, where element value is equal to its index.
    Returns the index if a fixed point exists, otherwise returns -1.
    """
    for i in range(len(arr)):
        if arr[i] == i:
            return i
    return -1

