def numIslands(grid):
    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return
        grid[i][j] = '0'
        dfs(grid, i + 1, j)
        dfs(grid, i - 1, j)
        dfs(grid, i, j + 1)
        dfs(grid, i, j - 1)

    if not grid:
        return 0

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                dfs(grid, i, j)
                count += 1
    return count

def longest_special_substring(s):
    """
    Finds the length of the longest special substring containing equal number of 'a's and 'b's.
    """
    max_length = 0
    balance = 0
    balance_map = {0: -1}

    for i, char in enumerate(s):
        if char == 'a':
            balance += 1
        else:
            balance -= 1

        if balance in balance_map:
            max_length = max(max_length, i - balance_map[balance])
        else:
            balance_map[balance] = i

    return max_length

