def can_reach_destination(grid, k):
    from collections import deque

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid_move(x, y, nx, ny):
        return 0 <= nx < rows and 0 <= ny < cols and abs(grid[nx][ny] - grid[x][y]) <= k

    queue = deque([(0, 0)])
    visited = set((0, 0))

    while queue:
        x, y = queue.popleft()

        if (x, y) == (rows - 1, cols - 1):
            return True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid_move(x, y, nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return False

def find_missing_element(nums1, nums2):
    """
    Returns the missing element that is present in nums1 but not in nums2.
    """
    element_counts = {}

    # Count elements in nums2
    for num in nums2:
        if num in element_counts:
            element_counts[num] += 1
        else:
            element_counts[num] = 1

    # Find the missing element in nums1
    for num in nums1:
        if num not in element_counts or element_counts[num] == 0:
            return num
        else:
            element_counts[num] -= 1

