def can_form_word(word, words_set, memo):
    """
    Helper function to determine if a word can be formed by concatenating
    other words in the set.
    """
    if word in memo:
        return memo[word]

    for i in range(1, len(word)):
        prefix = word[:i]
        suffix = word[i:]
        if prefix in words_set and (suffix in words_set or can_form_word(suffix, words_set, memo)):
            memo[word] = True
            return True

    memo[word] = False
    return False

def longest_concatenated_word(words):
    """
    Returns the longest string in words that can be constructed by concatenating
    other strings from words. If there is no such string, returns an empty string.
    """
    words_set = set(words)
    memo = {}
    longest_word = ""

    for word in words:
        if can_form_word(word, words_set, memo):
            if len(word) > len(longest_word):
                longest_word = word

    return longest_word

from collections import deque

def shortest_distance_to_building(grid):
    n = len(grid)
    if n == 0:
        return []

    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col, 0)])
        visited = set([(start_row, start_col)])
        distances = [[-1] * n for _ in range(n)]

        while queue:
            row, col, dist = queue.popleft()
            distances[row][col] = dist

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                r, c = row + dr, col + dc
                if 0 <= r < n and 0 <= c < n and (r, c) not in visited and grid[r][c] == 0:
                    visited.add((r, c))
                    queue.append((r, c, dist + 1))

        return distances

    result = [[-1] * n for _ in range(n)]
    for row in range(n):
        for col in range(n):
            if grid[row][col] == 0:
                result[row][col] = float('inf')
                for r in range(n):
                    for c in range(n):
                        if grid[r][c] == 1:
                            building_distances = bfs(r, c)
                            if building_distances[row][col] != -1:
                                result[row][col] = min(result[row][col], building_distances[row][col])

                if result[row][col] == float('inf'):
                    result[row][col] = -1

    return result

