def max_length_subarray(arr, d):
    """
    Returns the maximum length of a subarray where the absolute difference between
    the maximum value and the minimum value in the subarray does not exceed d.
    """
    from collections import deque

    if not arr:
        return 0

    max_len = 0
    min_dq, max_dq = deque(), deque()
    left = 0

    for right in range(len(arr)):
        while min_dq and arr[min_dq[-1]] >= arr[right]:
            min_dq.pop()
        while max_dq and arr[max_dq[-1]] <= arr[right]:
            max_dq.pop()

        min_dq.append(right)
        max_dq.append(right)

        while arr[max_dq[0]] - arr[min_dq[0]] > d:
            if min_dq[0] == left:
                min_dq.popleft()
            if max_dq[0] == left:
                max_dq.popleft()
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

