    def dfs(x, y, direction, shape):
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 1:
            grid[x][y] = 0
            shape.append(direction)
            dfs(x + 1, y, 'D', shape)
            dfs(x - 1, y, 'U', shape)
            dfs(x, y + 1, 'R', shape)
            dfs(x, y - 1, 'L', shape)
            shape.append('B')

    unique_islands = set()
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                shape = []
                dfs(i, j, 'O', shape)
                unique_islands.add(tuple(shape))

    return len(unique_islands)

