def max_participating_students(preferences):
    """
    Returns the maximum number of students that can participate in the competition.

    :param preferences: List[List[int]]
    :return: int
    """ 
    def dfs(student, visited, preferences):
        visited[student] = True
        count = 1  # including the current student

        for partner in preferences[student]:
            if not visited[partner]:
                count += dfs(partner, visited, preferences)

        return count

    n = len(preferences)
    if n == 0:
        return 0

    max_students = 0
    visited = [False] * n

    for student in range(n):
        if not visited[student] and preferences[student]:
            max_students = max(max_students, dfs(student, visited, preferences))

    return max_students

