def sunsetViews(heights):
    """
    Given an integer array heights representing the heights of buildings in a row,
    this function returns the indices of all "sunset view" buildings in ascending order of their indices.

    A building is considered a "sunset view" building if its height is greater than all the buildings to its right.
    """
    sunset_buildings = []
    max_height = -1

    for i in range(len(heights) - 1, -1, -1):
        if heights[i] > max_height:
            sunset_buildings.append(i)
            max_height = heights[i]

    return list(sorted(sunset_buildings))

