def length_of_longest_special_subarray(arr):
    """
    Returns the length of the longest special subarray from the given array.
    A special subarray has at least 3 distinct elements.
    """
    n = len(arr)
    if n < 3:
        return 0

    max_len = 0
    start = 0
    seen = {}

    for end in range(n):
        if arr[end] in seen and seen[arr[end]] >= start:
            start = seen[arr[end]] + 1
        seen[arr[end]] = end

        current_subarray_length = end - start + 1
        if current_subarray_length >= 3:
            max_len = max(max_len, current_subarray_length)

    return max_len

