def final_coordinates(s):
    """
    Returns the final coordinates of the robot after performing a series of moves.

    Parameters:
    s (str): A string representing a series of operations ('L', 'R', 'U', 'D').

    Returns:
    tuple: Final coordinates (x, y) of the robot.
    """
    x, y = 0, 0
    for move in s:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
    return (x, y)

