def valid_word_square(words):
    """
    Check if the given list of words forms a valid word square.

    :param words: List of strings, where each string represents a row.
    :return: True if the words form a valid word square, False otherwise.
    """
    n = len(words)
    for i in range(n):
        for j in range(len(words[i])):
            if j >= n or i >= len(words[j]) or words[i][j] != words[j][i]:
                return False
    return True

