def is_valid_parentheses(s):
    """
    Returns true if the string can be valid by replacing all '*' with '(', ')' or ''
    """
    left_balance = right_balance = 0
    for char in s:
        if char in '(*':
            left_balance += 1
        else:
            left_balance -= 1
        if char != '(':
            right_balance -= 1
        else:
            right_balance += 1
        if left_balance < 0:
            return False
        right_balance = max(right_balance, 0)
    return right_balance == 0

