def min_insertions_to_transform(s, t):
    """
    Returns the minimum number of insertions required to transform `s` into `t`.
    If it's not possible, returns -1.
    """
    si, ti = 0, 0

    while si < len(s) and ti < len(t):
        if s[si] == t[ti]:
            si += 1
        ti += 1

    # If some characters in `s` have not been matched, it's impossible to transform `s` into `t`
    if si != len(s):
        return -1

    # Number of insertions needed is the remaining unmatched characters in `t`
    return len(t) - len(s)

