def kthSmallestElement(arr, k):
    if not arr or k == 0:
        return None

    n = len(arr)
    if k > n:
        return None

    # Step 1: Sort the array
    arr.sort()

    # Step 2: Determine the size of each partition
    partition_size = n // k
    extra_elements = n % k

    partitions = []
    index = 0

    # Step 3: Create partitions
    for i in range(k):
        if i < extra_elements:
            partitions.append(arr[index:index + partition_size + 1])
            index += partition_size + 1
        else:
            partitions.append(arr[index:index + partition_size])
            index += partition_size

    # Step 4: Merge the partitions. We use a min-heap to efficiently find the kth element
    import heapq

    min_heap = []
    for partition in partitions:
        for num in partition:
            heapq.heappush(min_heap, num)

    # Step 5: Extract the kth smallest element
    for _ in range(k - 1):
        heapq.heappop(min_heap)

    return heapq.heappop(min_heap)

