def count_unique_subarrays(nums, k):
    """
    Returns the count of unique subarrays of length k with all distinct elements.
    """
    if len(nums) < k:
        return 0

    unique_subarrays = set()

    for i in range(len(nums) - k + 1):
        subarray = nums[i:i + k]
        if len(set(subarray)) == k:
            unique_subarrays.add(tuple(subarray))

    return len(unique_subarrays)

