def find_local_peaks(grid):
    """
    Return a list of coordinates (i, j) of all local peaks in the grid.
    A local peak is a cell that is strictly greater than all its adjacent cells.
    """
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    peaks = []

    def is_peak(r, c):
        # Check all four possible neighbors and compare
        current = grid[r][c]
        if r > 0 and grid[r-1][c] >= current:
            return False
        if r < rows-1 and grid[r+1][c] >= current:
            return False
        if c > 0 and grid[r][c-1] >= current:
            return False
        if c < cols-1 and grid[r][c+1] >= current:
            return False
        return True

    # Iterate through the grid
    for i in range(rows):
        for j in range(cols):
            if is_peak(i, j):
                peaks.append((i, j))
    return peaks

