def longest_palindromic_substring(st):
    """
    Returns the longest palindromic substring. 
    If there are multiple such substrings with the same length, 
    returns the one which appears first in lexicographical order.
    """

    def is_palindrome(s):
        return s == s[::-1]

    n = len(st)
    longest = ""

    for i in range(n):
        for j in range(i, n):
            current_substring = st[i:j+1]
            if is_palindrome(current_substring):
                if len(current_substring) > len(longest) or (len(current_substring) == len(longest) and current_substring < longest):
                    longest = current_substring    
    return longest

