def count_subarrays_with_sum(nums, target):
    """
    Returns the count of subarrays within `nums` that sum up to `target`.
    """
    count = 0
    current_sum = 0
    sum_counts = {0: 1}

    for num in nums:
        current_sum += num
        if current_sum - target in sum_counts:
            count += sum_counts[current_sum - target]
        if current_sum in sum_counts:
            sum_counts[current_sum] += 1
        else:
            sum_counts[current_sum] = 1

    return count

def longest_path_value_sum(n, edges, values):
    from collections import defaultdict, deque

    # Construct the graph
    graph = defaultdict(list)
    in_degree = [0] * n
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological Sort using Kahn's algorithm
    topo_order = []
    zero_in_degree_queue = deque([i for i in range(n) if in_degree[i] == 0])

    while zero_in_degree_queue:
        node = zero_in_degree_queue.popleft()
        topo_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree_queue.append(neighbor)

    # Early exit if there's a cycle and not all nodes are in topological order
    if len(topo_order) != n:
        return 0

    # Initialize distance with negative infinity
    dist = [-float('inf')] * n

    # Maximum path values starting from each vertex
    max_path_value = 0

    # Process vertices in topological order
    for node in topo_order:
        if dist[node] == -float('inf'):
            dist[node] = values[node]
        for neighbor in graph[node]:
            dist[neighbor] = max(dist[neighbor], dist[node] + values[neighbor])

    return max(dist)

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    n = len(s)
    if n == 0:
        return 0

    char_map = {}
    left = 0
    max_len = 0

    for right in range(n):
        if s[right] in char_map:
            left = max(left, char_map[s[right]] + 1)
        char_map[s[right]] = right
        max_len = max(max_len, right - left + 1)

    return max_len

