def generate_parenthesis(n):
    """
    Returns a list of unique combinations of n pairs of well-formed parentheses.
    """
    result = []

    def backtrack(current, open_count, close_count):
        if len(current) == 2 * n:
            result.append(current)
            return
        if open_count < n:
            backtrack(current + "(", open_count + 1, close_count)
        if close_count < open_count:
            backtrack(current + ")", open_count, close_count + 1)

    backtrack("", 0, 0)
    return result

def rob(nums, ownership):
    """
    Given a list of integers nums representing amount of money for each house 
    in a row and a list of booleans ownership representing whether you own the 
    house (True) or the thief owns the house (False), this function returns 
    the maximum amount of money you can rob given you can't rob two consecutive houses.
    """
    if not nums:
        return 0

    n = len(nums)
    # Initialize an array to store the maximum amounts
    dp = [0] * (n + 1)

    # Iterate through the houses
    for i in range(1, n + 1):
        if ownership[i - 1]:
            if i == 1:
                dp[i] = nums[i - 1]
            else:
                dp[i] = max(dp[i - 1], dp[i - 2] + nums[i - 1])
        else:
            dp[i] = dp[i - 1]

    return dp[n]

