def find_pairs(nums, target_sum):
    """
    Returns all unique pairs of integers from the list `nums` that add up to `target_sum`. 
    Each pair is sorted in ascending order, and the list of pairs is sorted based on the 
    first value of each pair.
    """
    nums.sort()
    pairs = set()
    seen = {}

    for num in nums:
        complement = target_sum - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen[num] = True

    return sorted(pairs)

