def minimum_difference(weights):
    """
    Returns the minimum possible difference between two groups formed from weights.
    """
    total_sum = sum(weights)
    n = len(weights)
    dp = [0] * (total_sum // 2 + 1)

    for weight in weights:
        for j in range(total_sum // 2, weight - 1, -1):
            dp[j] = max(dp[j], dp[j - weight] + weight)

    return abs(total_sum - 2 * dp[total_sum // 2])

