def min_steps_to_one(n):
    """
    Return the minimum number of steps required to reduce n to 1.
    """
    # Dictionary to store the minimum steps for each number
    dp = {1: 0}

    # Function to compute minimum steps using memoization
    def compute_steps(k):
        if k in dp:
            return dp[k]

        steps = compute_steps(k - 1) + 1
        if k % 2 == 0:
            steps = min(steps, compute_steps(k // 2) + 1)
        if k % 3 == 0:
            steps = min(steps, compute_steps(k // 3) + 1)

        dp[k] = steps
        return steps

    return compute_steps(n)

def find_top_manager(n, reportPairs):
    if n == 0:
        return -1

    # a set of all employee IDs
    all_employees = set(range(1, n+1))

    # a set of employees who report to someone
    has_manager = set(e for _, e in reportPairs)

    # find the set of employees who do not report to anyone
    top_managers = all_employees - has_manager

    if not top_managers:
        return -1

    # return the smallest ID among the top managers
    return min(top_managers)

def has_repeated_non_overlapping_substring(s):
    """
    Determines if there exists a non-empty substring that occurs at least twice in `s`, without overlapping.

    :param s: A string representing a sequence of characters.
    :return: True if there is a repeated non-overlapping substring, False otherwise.
    """
    length = len(s)
    for sub_len in range(1, length // 2 + 1):
        for i in range(length - sub_len * 2 + 1):
            if s[i:i + sub_len] == s[i + sub_len:i + sub_len * 2]:
                return True
    return False

