def longest_arithmetic_subarray(nums):
    if len(nums) < 2:
        return 0

    max_length = 2
    current_length = 2
    difference = nums[1] - nums[0]

    for i in range(2, len(nums)):
        if nums[i] - nums[i - 1] == difference:
            current_length += 1
        else:
            difference = nums[i] - nums[i - 1]
            current_length = 2

        max_length = max(max_length, current_length)

    return max_length

