def min_partitions(s):
    """
    Returns the minimum number of substrings such that each substring contains characters that are all the same.
    """
    if not s:
        return 0

    partitions = 1
    current_char = s[0]

    for char in s[1:]:
        if char != current_char:
            partitions += 1
            current_char = char

    return partitions

