def min_operations_to_match(words, target):
    """
    Determine the minimum number of operations required to change one string
    in `words` to exactly match the `target` string.

    :param words: list of strings
    :param target: string to match
    :return: minimum number of operations required
    """
    def operations_to_match(word, target):
        return sum(1 for w_char, t_char in zip(word, target) if w_char != t_char)

    return min(operations_to_match(word, target) for word in words if len(word) == len(target))

