def is_subsequence_of_any(s, t_list):
    """
    Returns True if any string in t_list is a subsequence of s, otherwise returns False.
    """
    def is_subsequence(s, t):
        t_len = len(t)
        s_index = 0
        t_index = 0
        while s_index < len(s) and t_index < t_len:
            if s[s_index] == t[t_index]:
                t_index += 1
            s_index += 1
        return t_index == t_len

    for t in t_list:
        if is_subsequence(s, t):
            return True

    return False

