def distinct_substrings(s, n):
    """
    Returns the number of distinct substrings of length n in the string s. 
    If n is greater than the length of s, return 0.
    """
    if n > len(s):
        return 0

    substrings = set()
    for i in range(len(s) - n + 1):
        substr = s[i:i+n]
        substrings.add(substr)

    return len(substrings)

