def check_subarray_sum(nums, k):
    """
    Check if there is a continuous subarray of length at least 2 that sums up to a multiple of k.

    :param nums: List of integers
    :param k: Integer
    :return: Boolean indicating if such a subarray exists
    """
    if not nums:
        return False

    prefix_sum = 0
    prefix_dict = {0: -1}  # To handle the case when the subarray that starts from index 0 has the desired sum
    for i, num in enumerate(nums):
        prefix_sum += num
        if k != 0:
            prefix_sum %= k

        if prefix_sum in prefix_dict:
            if i - prefix_dict[prefix_sum] > 1:
                return True
        else:
            prefix_dict[prefix_sum] = i

    return False

