def longest_path(board):
    def dfs(x, y, visited):
        longest = 0
        visited.add(board[x][y])

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and board[nx][ny] not in visited:
                longest = max(longest, dfs(nx, ny, visited))

        visited.remove(board[x][y])
        return longest + 1

    max_path = 0
    for i in range(len(board)):
        for j in range(len(board[0])):
            max_path = max(max_path, dfs(i, j, set()))

    return max_path

