def process_instructions(instructions):
    """
    Processes a list of instructions where each instruction is a list
    of format ["op", val1, val2] and performs the respective operation.

    Args:
        instructions (list): A list of instructions.

    Returns:
        list: A list of results after each operation.
    """
    results = []
    for instr in instructions:
        op, val1, val2 = instr
        if op == "add":
            results.append(val1 + val2)
        elif op == "multiply":
            results.append(val1 * val2)
        elif op == "subtract":
            results.append(val1 - val2)
        elif op == "divide":
            if val2 == 0:
                results.append("Invalid operation")
            else:
                results.append(val1 / val2)
        else:
            results.append("Invalid operation")

    return results

def longestSubstring(s, k):
    """
    Returns the length of the longest substring where every character appears at least `k` times.
    """
    def longest_substring_helper(s, k, start, end):
        if end - start < k:
            return 0

        count = [0] * 26

        for i in range(start, end):
            count[ord(s[i]) - ord('a')] += 1

        for mid in range(start, end):
            if count[ord(s[mid]) - ord('a')] >= k:
                continue

            next_mid = mid + 1
            while next_mid < end and count[ord(s[next_mid]) - ord('a')] < k:
                next_mid += 1

            return max(longest_substring_helper(s, k, start, mid),
                       longest_substring_helper(s, k, next_mid, end))

        return end - start

    return longest_substring_helper(s, k, 0, len(s))

